static int is_valid_file_type(struct stat *st) {
  if (S_ISREG(st->st_mode)) return 1;
  if (S_ISDIR(st->st_mode)) return 1;
  if (S_ISLNK(st->st_mode)) return 1;
  return 0;
}

static void read_file_list() {
  char *line = NULL;
  size_t len = 0;
  ssize_t nread;
  // we read from stdin
  while ((nread = getline(&line, &len, stdin)) != -1) {
    // remove trailing \n and \r
    while (nread > 0 && (line[nread-1]=='\n' || line[nread-1]=='\r')) {
      line[--nread] = '\0';
    }
    if (nread==0) continue; // skip empty lines
    char *orig = strdup(line);
    // lstat
    struct stat st;
    if (lstat(line, &st) != 0) {
      fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
      free(orig);
      continue;
    }
    if (!is_valid_file_type(&st)) {
      // not regular file, skip (like fifo, char device)
      free(orig);
      continue;
    }
    // add
    files = realloc(files, (n_files+1)*sizeof(FileEnt));
    files[n_files].orig = orig;
    files[n_files].real = strdup(line);
    files[n_files].st = st;
    files[n_files].is_dir = S_ISDIR(st.st_mode);
    files[n_files].is_symlink = S_ISLNK(st.st_mode);
    n_files++;
  }
  free(line);
  if (n_files==0) {
    fprintf(stderr, "%s: No regular files to watch\n", progname);
    exit(1);
  }
}

static void setup_tty() {
  if (flag_n) {
    tty_fd = -1;
    return;
  }
  tty_fd = open("/dev/tty", O_RDWR);
  if (tty_fd < 0) {
    fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
    exit(1);
  }
  struct termios t;
  if (tcgetattr(tty_fd, &t)==-1) {
    fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
    exit(1);
  }
  orig_termios = t;
  termios_saved = 1;
  t.c_lflag &= ~(ICANON | ECHO);
  t.c_cc[VMIN] = 1;
  t.c_cc[VTIME] = 0;
  if (tcsetattr(tty_fd, TCSANOW, &t)==-1) {
    // ignore
  }
}

static void restore_tty() {
  if (termios_saved && tty_fd >=0) {
    tcsetattr(tty_fd, TCSANOW, &orig_termios);
  }
}

static void setup_signal_handlers() {
  struct sigaction sa;
  memset(&sa,0,sizeof(sa));
  sa.sa_handler = sigint_handler;
  sigaction(SIGINT, &sa, NULL);
  sa.sa_handler = sigterm_handler;
  sigaction(SIGTERM, &sa, NULL);
  // Ignore SIGPIPE for awk pipe
  signal(SIGPIPE, SIG_IGN);
}

static int parse_restart_signal() {
  char *env = getenv("ENTR_RESTART_SIGNAL");
  if (!env) return SIGTERM;
  if (strcmp(env, "HUP")==0) return SIGHUP;
  if (strcmp(env, "INT")==0) return SIGINT;
  if (strcmp(env, "QUIT")==0) return SIGQUIT;
  if (strcmp(env, "TERM")==0) return SIGTERM;
  if (strcmp(env, "USR1")==0) return SIGUSR1;
  if (strcmp(env, "USR2")==0) return SIGUSR2;
  // If invalid, original didn't error, just default? We saw invalid still allowed run, so default to TERM
  return SIGTERM;
}

