static void send_status(const char *type, int code, const char *util) {
  if (!flag_x) return;
  if (awk_fd < 0) return;
  char buf[1024];
  // type is "exit" or "signal"
  // code: for exit, exit code, for signal, signal number
  // util: utility name (e.g., "echo", "sh")
  snprintf(buf, sizeof(buf), "%s|%d|%s\n", type, code, util);
  ssize_t n = write(awk_fd, buf, strlen(buf));
  (void)n;
  // If write fails (EPIPE), awk terminated
  if (n < 0) {
    if (errno == EPIPE) {
      // awk died
      fprintf(stderr, "%s: status process terminated\n", progname);
      close(awk_fd);
      awk_fd = -1;
      // wait for awk?
      int status;
      waitpid(awk_pid, &status, 0);
      awk_pid = -1;
      // For -z mode, original printed "status process terminated" and then? Let's see behavior: with -z and awk failing early, what does entr do?
