      // We need to decide: if awk dies, print message and continue? For -z, should exit?
      // According to earlier, when awk failed with mawk, it printed "status process terminated" and then exit 0 (without -z) or exit 5 (with -z?) Let's see:
      // With -x and mawk, second run gave EXIT 0 (timeout killed). So it continued.
      // For our implementation, print message and continue, disable further status.
    }
  }
}

static char *get_util_name(char **argv, int argc, int is_s) {
  if (is_s) {
    return "sh";
  } else {
    if (argc>0) {
      // basename?
      char *b = my_basename(argv[0]);
      return b;
    } else {
      return "unknown";
    }
  }
}

static void clear_screen() {
  if (flag_c == 1) {
    const char *seq = "\033[2J\033[H";
    write(STDOUT_FILENO, seq, strlen(seq));
  } else if (flag_c >= 2) {
    const char *seq = "\033[2J\033[3J\033[H";
    write(STDOUT_FILENO, seq, strlen(seq));
  }
}

// Run utility in normal mode, returns exit status (0-255) and sets *signaled and *sig
static int run_utility_normal(char **util_argv, int util_argc, const char *trigger, int *out_signaled, int *out_sig) {
  clear_screen();
  pid_t pid = fork();
  if (pid < 0) die("fork");
  if (pid==0) {
    // child
    // Set PAGER
    setenv("PAGER", "/bin/cat", 1);
    // Restore tty? For normal mode, child should have tty? Original says TTY opened before watch loop to support interactive utilities.
    // For -r mode, control of TTY not transferred.
    // For normal mode, it should have tty? But we already have tty_fd open, child inherits.
    // Also need to handle /_ replacement was done before calling.
    // For -s mode, args are different
    if (flag_s) {
      char *shell = getenv("SHELL");
      if (!shell) shell = "/bin/sh";
      // util_argv[0] is shell command string
      // We need to exec shell -c command trigger
      execlp(shell, shell, "-c", util_argv[0], trigger ? trigger : "", (char*)NULL);
      fprintf(stderr, "%s: exec %s: %s\n", progname, shell, strerror(errno));
      _exit(127);
    } else {
      execvp(util_argv[0], util_argv);
      fprintf(stderr, "%s: exec %s: %s\n", progname, util_argv[0], strerror(errno));
      _exit(127);
    }
  } else {
    int status;
    // Wait
    while (waitpid(pid, &status, 0) < 0) {
      if (errno == EINTR) {
        if (got_sigint) {
          // If SIGINT received while waiting for child, should we kill child?
          // In original, SIGINT causes entr to exit 0 after child? Let's check.
          // For normal mode, when SIGINT received, it should terminate? We have handler that sets flag, but we need to forward?
          // Typically, entr should kill child on SIGINT? Let's see earlier test: when child is sleep 10 and entr gets SIGINT, child should be killed?
          // We saw when we sent SIGINT to entr while it was running child (sleep 10), entr exited 0 quickly, meaning child was killed or left?
          // Let's assume we kill child on SIGINT?
          // For now, kill child with SIGTERM
          kill(pid, SIGTERM);
        }
        if (got_sigterm) {
          kill(pid, SIGTERM);
        }
        continue;
      } else {
        break;
      }
    }
    if (WIFEXITED(status)) {
      *out_signaled = 0;
      *out_sig = 0;
      return WEXITSTATUS(status);
    } else if (WIFSIGNALED(status)) {
      *out_signaled = 1;
      *out_sig = WTERMSIG(status);
      return 128 + WTERMSIG(status);
    } else {
      *out_signaled = 0;
      *out_sig = 0;
      return 0;
    }
  }
  return 0;
}

// For -r mode, start child and keep pid
static pid_t start_child_r(char **util_argv, int util_argc, const char *trigger) {
  clear_screen();
  pid_t pid = fork();
  if (pid < 0) die("fork");
  if (pid==0) {
    // child: create process group
    setpgid(0,0);
    setenv("PAGER", "/bin/cat", 1);
    if (flag_s) {
      char *shell = getenv("SHELL");
      if (!shell) shell = "/bin/sh";
      execlp(shell, shell, "-c", util_argv[0], trigger ? trigger : "", (char*)NULL);
      fprintf(stderr, "%s: exec %s: %s\n", progname, shell, strerror(errno));
      _exit(127);
    } else {
      execvp(util_argv[0], util_argv);
      fprintf(stderr, "%s: exec %s: %s\n", progname, util_argv[0], strerror(errno));
      _exit(127);
    }
  } else {
    // parent: set pgid if not already
    setpgid(pid, pid);
    return pid;
  }
  return -1;
}

// Check if file still exists, if not print cannot open and exit 1
static void check_file_exists(const char *orig) {
  struct stat st;
  if (lstat(orig, &st)!=0) {
    fprintf(stderr, "%s: cannot open '%s': No such file or directory\n", progname, orig);
    exit(1);
  }
}

