  int i = 1;
  int util_start = -1;
  while (i < argc) {
    if (strcmp(argv[i], "--")==0) {
      util_start = i+1;
      break;
    }
    if (argv[i][0] != '-' || strcmp(argv[i], "-")==0) {
      util_start = i;
      break;
    }
    // It's option(s)
    char *p = argv[i]+1;
    if (strlen(p)==0) {
      // "-" alone? treat as utility?
      util_start = i;
      break;
    }
    while (*p) {
      switch (*p) {
        case 'a': flag_a = 1; break;
        case 'c': flag_c++; break;
        case 'd': flag_d++; break;
        case 'n': flag_n = 1; break;
        case 'p': flag_p = 1; break;
        case 'r': flag_r = 1; break;
        case 's': flag_s = 1; break;
        case 'x': flag_x++; break;
        case 'z': flag_z = 1; break;
        case 'h':
