          exit(1);
        default:
          fprintf(stderr, "%s: invalid option -- '%c'\n", progname, *p);
          print_usage(0);
          exit(1);
      }
      p++;
    }
    i++;
  }
  if (util_start==-1) {
    // No utility
    print_usage(1);
    exit(1);
  }
  if (util_start >= argc) {
    print_usage(0);
    exit(1);
  }
  char **util_argv = argv + util_start;
  int util_argc = argc - util_start;

  // Validate -s requires single argument
  if (flag_s && util_argc != 1) {
    fprintf(stderr, "%s: -s requires commands to be formatted as a single argument\n", progname);
    exit(1);
  }

  // Read file list from stdin
  read_file_list();

  // Set PAGER always to /bin/cat (overwrites)
  setenv("PAGER", "/bin/cat", 1);
  // Actually original sets PAGER to /bin/cat unconditionally, but also sets? We already did, but for child we set again.

  setup_signal_handlers();
  setup_tty();
  setup_inotify_watches();

  restart_sig = parse_restart_signal();

  // Setup awk status
  setup_awk();

  // Trigger file initially first file orig
  if (n_files>0) {
    trigger_file = files[0].orig;
  }

  // For -p, postpone first execution
  int first = 1;
  int dir_altered_pending = 0;
  char *dir_altered_trigger = NULL;

  // For -r mode
  pid_t r_child = -1;
  int r_child_exit_code = 0;
  int r_child_signaled = 0;
  int r_child_sig = 0;

  // For normal mode loop
  if (flag_r) {
    // -r mode
    if (!flag_p) {
      // start child immediately
      // Build argv for child with trigger replacement if needed
      char **run_argv;
      int run_argc;
      if (flag_s) {
        run_argv = util_argv;
        run_argc = util_argc;
      } else {
        // handle /_ replacement
        run_argv = malloc((util_argc+1)*sizeof(char*));
        run_argc = util_argc;
