          int child_done = 0;
          int child_status = 0;
          int child_signaled = 0;
          int child_sig = 0;
          int new_pending = 0;
          char *new_pending_trigger = NULL;
          int new_pending_dir_altered = 0;
          char *new_pending_dir_trigger = NULL;

          while (!child_done) {
            struct pollfd pfds2[2];
            int nfds2=0;
            pfds2[nfds2].fd=inotify_fd;
            pfds2[nfds2].events=POLLIN;
            nfds2++;
            if (tty_fd>=0) {
