                      else new_pending=1;
                      new_pending_trigger = watches[widx].orig;
                    }
                  } else if (didx!=-1) {
                    struct stat st;
                    if (stat(dirwatches[didx].dir_path, &st)!=0) {
                      // dir removed?
                      new_pending = 1;
                      new_pending_trigger = dirwatches[didx].orig_for_dir;
                      new_pending_dir_altered = 1;
                      new_pending_dir_trigger = dirwatches[didx].orig_for_dir;
                    } else {
                      int include_dot = (flag_d>=2);
                      int n_new;
                      char **new_list = list_dir(dirwatches[didx].dir_path, &n_new, include_dot);
                      int altered = cmp_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries, new_list, n_new)!=0;
                      int workaround = getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
                      int handled_as_file_mod = 0;
                      if (workaround && ev->len>0) {
                        for (int fi=0; fi<n_files; fi++) {
                          char *parent = my_dirname(files[fi].real);
                          if (parent && strcmp(parent, dirwatches[didx].dir_path)==0) {
                            if (strcmp(ev->name, my_basename(files[fi].real))==0) {
                              if (flag_a) new_pending++;
                              else new_pending=1;
                              new_pending_trigger = files[fi].orig;
                              handled_as_file_mod=1;
                              free(parent);
                              break;
                            }
                          }
                          if (parent) free(parent);
                        }
                      }
                      if (!handled_as_file_mod && altered) {
                        free_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries);
                        dirwatches[didx].entries = new_list;
                        dirwatches[didx].n_entries = n_new;
                        new_pending_dir_altered = 1;
                        new_pending_dir_trigger = dirwatches[didx].orig_for_dir;
                        if (flag_a) new_pending++;
                        else new_pending=1;
                        new_pending_trigger = dirwatches[didx].orig_for_dir;
                      } else if (!handled_as_file_mod) {
                        free_str_list(new_list, n_new);
                      } else {
                        free_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries);
                        dirwatches[didx].entries = new_list;
                        dirwatches[didx].n_entries = n_new;
                      }
                    }
                  }
                  ptr += sizeof(struct inotify_event) + ev->len;
                }
              }
            }
          }

          // Child done
          if (!flag_s) free(run_argv);

          int exit_code;
          if (WIFEXITED(child_status)) exit_code = WEXITSTATUS(child_status);
          else if (WIFSIGNALED(child_status)) exit_code = 128 + WTERMSIG(child_status);
          else exit_code = 0;

          char *util_name = get_util_name(util_argv, util_argc, flag_s);
          if (child_signaled) send_status("signal", child_sig, util_name);
          else send_status("exit", exit_code, util_name);

          if (flag_z) {
            restore_tty();
            if (awk_fd>=0) close(awk_fd);
            if (awk_pid>0) waitpid(awk_pid,NULL,0);
            exit(exit_code);
          }

          if (new_pending_dir_altered) {
            // After this run, exit 2
            // But we already ran once for the trigger? In our loop, we just finished child run that was triggered by previous event.
            // If dir altered occurred during child run, we have already queued next run (new_pending). Should run one more time then exit 2.
            // Let's handle: if dir altered flag set, after child finishes, run once more then exit 2.
            // For simplicity, if new_pending_dir_altered, we do one more run with dir trigger, then exit 2.
            if (new_pending) {
