              }
              int sig2=0, signaled2=0;
              int code2 = run_utility_normal(run_argv2, util_argc, use_trigger, &signaled2, &sig2);
              if (!flag_s) free(run_argv2);
              char *util_name2 = get_util_name(util_argv, util_argc, flag_s);
              if (signaled2) send_status("signal", sig2, util_name2);
              else send_status("exit", code2, util_name2);
              if (flag_z) {
