                char *use_trigger = new_pending_trigger;
                trigger_file = use_trigger;
                char **run_argv2;
                if (flag_s) run_argv2=util_argv;
                else {
                  run_argv2=malloc((util_argc+1)*sizeof(char*));
                  int repl=0;
                  for (int j=0;j<util_argc;j++) {
                    if (!repl && strcmp(util_argv[j], "/_")==0){run_argv2[j]=use_trigger; repl=1;} else run_argv2[j]=util_argv[j];
                  }
                  run_argv2[util_argc]=NULL;
                }
                int s2=0, sig2=0;
                int c2 = run_utility_normal(run_argv2, util_argc, use_trigger, &s2, &sig2);
                if (!flag_s) free(run_argv2);
                char *un2 = get_util_name(util_argv, util_argc, flag_s);
                if (s2) send_status("signal", sig2, un2);
                else send_status("exit", c2, un2);
                if (flag_z) { restore_tty(); if (awk_fd>=0) close(awk_fd); if (awk_pid>0) waitpid(awk_pid,NULL,0); exit(c2); }
              }
              pending = 1;
              pending_trigger = new_pending_trigger;
            } else {
              pending = 1;
              pending_trigger = new_pending_trigger;
            }
          } else {
            pending = 0;
          }

          // Also check dir altered that happened during run but not yet handled? Already handled above for exit 2, but if not exit, continue

          // If no pending, go back to poll loop
          // If pending, continue loop to run again (while pending handles at top)
          if (pending_dir_altered) {
