            fprintf(stderr, "%s: directory altered\n", progname);
            restore_tty();
            if (awk_fd>=0) close(awk_fd);
            if (awk_pid>0) waitpid(awk_pid,NULL,0);
            exit(2);
          }
        }

        // If we reach here without handling child run via custom loop, we need to handle pending from earlier poll that was outside child run
        // Actually our custom loop already handles child run and pending
        // So outer while pending loop should continue
        // But we already handled inside
