static char *my_basename(char *path) {
  char *b = strrchr(path, '/');
  if (b) return b+1;
  return path;
}

static char *my_dirname(const char *path) {
  // returns malloced dirname
  char *copy = strdup(path);
  if (!copy) return NULL;
  char *dir = dirname(copy);
  char *res = strdup(dir);
  free(copy);
  return res;
}

static int is_dotfile(const char *name) {
  return name[0] == '.';
}

// snapshot dir entries
static char **list_dir(const char *dir_path, int *out_n, int include_dot) {
  DIR *d = opendir(dir_path);
  if (!d) return NULL;
  char **list = NULL;
  int n = 0, cap = 0;
  struct dirent *ent;
  while ((ent = readdir(d)) != NULL) {
    if (strcmp(ent->d_name, ".")==0 || strcmp(ent->d_name, "..")==0) continue;
    if (!include_dot && is_dotfile(ent->d_name)) continue;
    if (n >= cap) {
      cap = cap ? cap*2 : 64;
      list = realloc(list, cap * sizeof(char*));
    }
    list[n++] = strdup(ent->d_name);
  }
  closedir(d);
  // sort for comparison
  if (list) qsort(list, n, sizeof(char*), (int(*)(const void*, const void*))strcmp);
  // Actually qsort with strcmp not correct for char**; need wrapper
  // Let's use simple bubble? Small n. Use qsort with proper comparator
  // We'll fix comparator
  // For now, sort via custom
  for (int i=0;i<n;i++) for (int j=i+1;j<n;j++) if (strcmp(list[i], list[j])>0) { char *tmp=list[i]; list[i]=list[j]; list[j]=tmp; }
  *out_n = n;
  return list;
}

static int cmp_str_list(char **a, int na, char **b, int nb) {
  if (na != nb) return 1;
  for (int i=0;i<na;i++) if (strcmp(a[i], b[i])!=0) return 1;
  return 0;
}

static void free_str_list(char **list, int n) {
  if (!list) return;
  for (int i=0;i<n;i++) free(list[i]);
  free(list);
}

static int find_dirwatch_by_path(const char *dir_path) {
  for (int i=0;i<n_dirwatches;i++) {
    if (strcmp(dirwatches[i].dir_path, dir_path)==0) return i;
  }
  return -1;
}

static int find_watch_by_wd(int wd) {
  for (int i=0;i<n_watches;i++) if (watches[i].wd == wd) return i;
  return -1;
}

static int find_dirwatch_by_wd(int wd) {
  for (int i=0;i<n_dirwatches;i++) if (dirwatches[i].wd == wd) return i;
  return -1;
}

static void add_watch_entry(const char *orig, const char *watch_path, int is_dir_input, int is_parent) {
  if (n_watches >= watches_cap) {
    watches_cap = watches_cap ? watches_cap*2 : 64;
    watches = realloc(watches, watches_cap * sizeof(WatchEntry));
  }
  watches[n_watches].orig = strdup(orig);
  watches[n_watches].watch_path = strdup(watch_path);
  watches[n_watches].wd = -1;
  watches[n_watches].is_dir_input = is_dir_input;
  watches[n_watches].is_parent_watch = is_parent;
  n_watches++;
}

static void add_dirwatch(const char *dir_path, const char *orig_for_dir) {
  if (find_dirwatch_by_path(dir_path) != -1) return;
  if (n_dirwatches >= dirwatches_cap) {
    dirwatches_cap = dirwatches_cap ? dirwatches_cap*2 : 64;
    dirwatches = realloc(dirwatches, dirwatches_cap * sizeof(DirWatch));
  }
  dirwatches[n_dirwatches].dir_path = strdup(dir_path);
  dirwatches[n_dirwatches].orig_for_dir = strdup(orig_for_dir);
  dirwatches[n_dirwatches].entries = NULL;
  dirwatches[n_dirwatches].n_entries = 0;
  dirwatches[n_dirwatches].wd = -1;
  n_dirwatches++;
}

static void setup_inotify_watches() {
  inotify_fd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
  if (inotify_fd < 0) die("inotify_init1");

  // Optionally print open_max?
  if (ev_trace) {
    // get open max via sysconf?
    long open_max = sysconf(_SC_OPEN_MAX);
    if (open_max < 0) open_max = 1024;
    fprintf(stderr, "open_max: %ld\n", open_max);
  }

  int follow = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
  int workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;
  if (workaround && ev_trace) {
    fprintf(stderr, "executable: broken inotify workaround enabled\n");
  }

  int include_dot = (flag_d >= 2);

  // First, file watches
  for (int i=0;i<n_files;i++) {
    char *orig = files[i].orig;
    char *watch_path = files[i].real; // as given
    int is_dir = files[i].is_dir;

    if (is_dir) {
      // directory input: add dir watch
      add_dirwatch(watch_path, orig);
    } else {
      // regular file or symlink
      if (workaround) {
        // watch parent dir instead of file
        char *parent = my_dirname(watch_path);
        if (parent) {
          add_dirwatch(parent, orig);
          free(parent);
        }
        // Also add file watch? For workaround, file modification reported via dir, so we still need parent watch only.
        // But we also add file watch? Let's not.
      } else {
        // watch file itself
        // Determine actual path to watch: if follow and symlink, resolve?
        char *actual = watch_path;
        char resolved[PATH_MAX];
        if (follow) {
          // try realpath, but if fails (broken), use watch_path
          if (realpath(watch_path, resolved) != NULL) {
            actual = resolved;
            // need to keep string? We'll strdup later
            add_watch_entry(orig, actual, 0, 0);
            continue;
          }
        }
        add_watch_entry(orig, watch_path, 0, 0);
      }
    }
  }

  // For -d, add parent dir watches for files
  if (flag_d) {
    for (int i=0;i<n_files;i++) {
      if (files[i].is_dir) continue; // already dir watch for dir inputs
      char *watch_path = files[i].real;
      char *parent = my_dirname(watch_path);
      if (!parent) continue;
      add_dirwatch(parent, files[i].orig);
      free(parent);
    }
  }

  // Now create inotify watches for file entries
  for (int i=0;i<n_watches;i++) {
    uint32_t mask = IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE | IN_DELETE_SELF | IN_MOVE_SELF;
    if (!follow) mask |= IN_DONT_FOLLOW;
    int wd = inotify_add_watch(inotify_fd, watches[i].watch_path, mask);
    if (wd < 0) {
      // file may have been deleted already? We'll handle later via cannot open
      // Don't fatal, but keep wd -1
      if (ev_trace) {
        fprintf(stderr, "inotify watch failed for %s: %s\n", watches[i].watch_path, strerror(errno));
      }
      continue;
    }
    watches[i].wd = wd;
    if (ev_trace) {
      // print "0/1: fflags: 0x2 r 100644 /path"? Let's mimic format we saw:
      // Format: "<index>/<total>: fflags: <hex> <type> <mode> <path>"
      // We saw "0/1: fflags: 0x2 r 100644 /tmp/..."
      // For dir: "0/1: fflags: 0x2 d 40700 /tmp/..."
      // But we need fflags mapping? Original shows 0x2 for something (maybe IN_MODIFY?)
      // Let's try to reproduce similar to what original prints: it prints fflags hex, then type char (r for regular, d for dir), then mode, then path.
      // For simplicity, print something similar.
      // We'll compute mode from stat if available
      struct stat st;
      int is_dir = 0;
      char type_c = '?';
      mode_t mode = 0;
      if (lstat(watches[i].watch_path, &st)==0) {
        mode = st.st_mode & 07777;
        if (S_ISDIR(st.st_mode)) { is_dir = 1; type_c = 'd'; }
        else if (S_ISREG(st.st_mode)) { type_c = 'r'; }
        else if (S_ISLNK(st.st_mode)) { type_c = 'l'; }
        else type_c = '?';
      } else {
        type_c = 'r';
        mode = 0644;
      }
      // fflags 0x2 is IN_MODIFY? Let's just print 0x2
      fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n", i, n_watches + n_dirwatches -1, 2, type_c, mode, watches[i].watch_path);
    }
  }

  // Dir watches
  for (int i=0;i<n_dirwatches;i++) {
    // snapshot entries
    int n;
    char **list = list_dir(dirwatches[i].dir_path, &n, include_dot);
    dirwatches[i].entries = list;
    dirwatches[i].n_entries = n;

    uint32_t mask = IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO | IN_DELETE_SELF | IN_MOVE_SELF | IN_ATTRIB | IN_MODIFY;
    if (workaround) {
      mask |= IN_CLOSE_WRITE;
    }
    if (!follow) mask |= IN_DONT_FOLLOW;
    // For dir, also IN_ONLYDIR?
    int wd = inotify_add_watch(inotify_fd, dirwatches[i].dir_path, mask);
    if (wd < 0) {
      if (ev_trace) fprintf(stderr, "inotify dir watch failed %s: %s\n", dirwatches[i].dir_path, strerror(errno));
      // If dir doesn't exist, print unable to open directory?
      fprintf(stderr, "%s: unable to open directory: '%s'\n", progname, dirwatches[i].dir_path);
      // According to earlier, when dir removed, it printed unable to open directory and exited 1?
      // For initial setup, if dir doesn't exist, we should maybe error?
      // But original seems to allow? Let's continue
      continue;
    }
    dirwatches[i].wd = wd;
    if (ev_trace) {
      // For dir, print similar
      // We need to find index overall
      struct stat st;
      mode_t mode = 0;
      char type_c = 'd';
      if (stat(dirwatches[i].dir_path, &st)==0) {
        mode = st.st_mode & 07777;
      } else {
        mode = 0700;
      }
      // The original printed "0/1: fflags: 0x2 d 40700 /tmp/..."
      // For dir watches, after file watches, continue index?
      // We'll approximate: print with dir type
      int total = n_watches + n_dirwatches;
      int idx = n_watches + i;
      fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n", idx, total-1, 2, type_c, mode, dirwatches[i].dir_path);
    }
  }
}

static int is_valid_file_type(struct stat *st) {
  if (S_ISREG(st->st_mode)) return 1;
  if (S_ISDIR(st->st_mode)) return 1;
  if (S_ISLNK(st->st_mode)) return 1;
  return 0;
}

static void read_file_list() {
  char *line = NULL;
  size_t len = 0;
  ssize_t nread;
  // we read from stdin
  while ((nread = getline(&line, &len, stdin)) != -1) {
    // remove trailing \n and \r
    while (nread > 0 && (line[nread-1]=='\n' || line[nread-1]=='\r')) {
      line[--nread] = '\0';
    }
    if (nread==0) continue; // skip empty lines
    char *orig = strdup(line);
    // lstat
    struct stat st;
    if (lstat(line, &st) != 0) {
      fprintf(stderr, "%s: unable to stat '%s'\n", progname, line);
      free(orig);
      continue;
    }
    if (!is_valid_file_type(&st)) {
      // not regular file, skip (like fifo, char device)
      free(orig);
      continue;
    }
    // add
    files = realloc(files, (n_files+1)*sizeof(FileEnt));
    files[n_files].orig = orig;
    files[n_files].real = strdup(line);
    files[n_files].st = st;
    files[n_files].is_dir = S_ISDIR(st.st_mode);
    files[n_files].is_symlink = S_ISLNK(st.st_mode);
    n_files++;
  }
  free(line);
  if (n_files==0) {
    fprintf(stderr, "%s: No regular files to watch\n", progname);
    exit(1);
  }
}

static void setup_tty() {
  if (flag_n) {
    tty_fd = -1;
    return;
  }
  tty_fd = open("/dev/tty", O_RDWR);
  if (tty_fd < 0) {
    fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
    exit(1);
  }
  struct termios t;
  if (tcgetattr(tty_fd, &t)==-1) {
    fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", progname);
    exit(1);
  }
  orig_termios = t;
  termios_saved = 1;
  t.c_lflag &= ~(ICANON | ECHO);
  t.c_cc[VMIN] = 1;
  t.c_cc[VTIME] = 0;
  if (tcsetattr(tty_fd, TCSANOW, &t)==-1) {
    // ignore
  }
}

static void restore_tty() {
  if (termios_saved && tty_fd >=0) {
    tcsetattr(tty_fd, TCSANOW, &orig_termios);
  }
}

static void setup_signal_handlers() {
  struct sigaction sa;
  memset(&sa,0,sizeof(sa));
  sa.sa_handler = sigint_handler;
  sigaction(SIGINT, &sa, NULL);
  sa.sa_handler = sigterm_handler;
  sigaction(SIGTERM, &sa, NULL);
  // Ignore SIGPIPE for awk pipe
  signal(SIGPIPE, SIG_IGN);
}

static int parse_restart_signal() {
  char *env = getenv("ENTR_RESTART_SIGNAL");
  if (!env) return SIGTERM;
  if (strcmp(env, "HUP")==0) return SIGHUP;
  if (strcmp(env, "INT")==0) return SIGINT;
  if (strcmp(env, "QUIT")==0) return SIGQUIT;
  if (strcmp(env, "TERM")==0) return SIGTERM;
  if (strcmp(env, "USR1")==0) return SIGUSR1;
  if (strcmp(env, "USR2")==0) return SIGUSR2;
  // If invalid, original didn't error, just default? We saw invalid still allowed run, so default to TERM
  return SIGTERM;
}

