int main(int argc, char *argv[]) {
  progname = argv[0];
  // For error messages, original uses "executable" even though binary named executable? In tests, messages say "executable: ..." So progname from argv[0] is "./executable", but they print "executable: ..."? Actually we saw "executable: No regular files..." So they use basename of progname? Let's keep progname as basename? For simplicity, we'll set progname = "executable" or basename(argv[0]).
  // In earlier tests, errors printed "executable: ..." when binary is ./executable, so they use argv[0] as given? "./executable" would print "./executable: ...", but we saw "executable: ...". So they probably use basename or hardcoded "executable"? Let's use basename.
  progname = my_basename(argv[0]);
  // But to match original messages exactly, they printed "executable: ..." (without ./). So basename makes sense.
  // However for status created message, they printed "entr: created ..." not using progname. So we need to hardcode "entr" for that message.

  // Check env trace
  if (getenv("EV_TRACE")) ev_trace = 1;

  // Parse options
  int opt;
  // Use getopt
  // Note: need to support -h, -a, -c, -d, -n, -p, -r, -s, -x, -z
  // c and d and x can be repeated
  // Also support -- to end options
  int i = 1;
  int util_start = -1;
  while (i < argc) {
    if (strcmp(argv[i], "--")==0) {
      util_start = i+1;
      break;
    }
    if (argv[i][0] != '-' || strcmp(argv[i], "-")==0) {
      util_start = i;
      break;
    }
    // It's option(s)
    char *p = argv[i]+1;
    if (strlen(p)==0) {
      // "-" alone? treat as utility?
      util_start = i;
      break;
    }
    while (*p) {
      switch (*p) {
        case 'a': flag_a = 1; break;
        case 'c': flag_c++; break;
        case 'd': flag_d++; break;
        case 'n': flag_n = 1; break;
        case 'p': flag_p = 1; break;
        case 'r': flag_r = 1; break;
        case 's': flag_s = 1; break;
        case 'x': flag_x++; break;
        case 'z': flag_z = 1; break;
        case 'h':
          print_usage(1);
          exit(1);
        default:
          fprintf(stderr, "%s: invalid option -- '%c'\n", progname, *p);
          print_usage(0);
          exit(1);
      }
      p++;
    }
    i++;
  }
  if (util_start==-1) {
    // No utility
    print_usage(1);
    exit(1);
  }
  if (util_start >= argc) {
    print_usage(0);
    exit(1);
  }
  char **util_argv = argv + util_start;
  int util_argc = argc - util_start;

  // Validate -s requires single argument
  if (flag_s && util_argc != 1) {
    fprintf(stderr, "%s: -s requires commands to be formatted as a single argument\n", progname);
    exit(1);
  }

  // Read file list from stdin
  read_file_list();

  // Set PAGER always to /bin/cat (overwrites)
  setenv("PAGER", "/bin/cat", 1);
  // Actually original sets PAGER to /bin/cat unconditionally, but also sets? We already did, but for child we set again.

  setup_signal_handlers();
  setup_tty();
  setup_inotify_watches();

  restart_sig = parse_restart_signal();

  // Setup awk status
  setup_awk();

  // Trigger file initially first file orig
  if (n_files>0) {
    trigger_file = files[0].orig;
  }

  // For -p, postpone first execution
  int first = 1;
  int dir_altered_pending = 0;
  char *dir_altered_trigger = NULL;

  // For -r mode
  pid_t r_child = -1;
  int r_child_exit_code = 0;
  int r_child_signaled = 0;
  int r_child_sig = 0;

  // For normal mode loop
  if (flag_r) {
    // -r mode
    if (!flag_p) {
      // start child immediately
      // Build argv for child with trigger replacement if needed
      char **run_argv;
      int run_argc;
      if (flag_s) {
        run_argv = util_argv;
        run_argc = util_argc;
      } else {
        // handle /_ replacement
        run_argv = malloc((util_argc+1)*sizeof(char*));
        run_argc = util_argc;
        int replaced = 0;
        for (int j=0;j<util_argc;j++) {
          if (!replaced && strcmp(util_argv[j], "/_")==0) {
            run_argv[j] = trigger_file ? trigger_file : files[0].orig;
            replaced = 1;
          } else {
            run_argv[j] = util_argv[j];
          }
        }
        run_argv[util_argc]=NULL;
      }
      r_child = start_child_r(run_argv, run_argc, trigger_file);
      if (!flag_s) free(run_argv);
    }

    // Main poll loop for -r
    while (1) {
      if (got_sigint) {
        restore_tty();
        if (r_child>0) {
          // kill child?
          kill(-r_child, SIGTERM);
          // wait?
          waitpid(r_child, NULL, 0);
        }
        if (flag_z && r_child) {
          // exit with child's code? But we got sigint, exit 0?
          exit(0);
        } else {
          exit(0);
        }
      }
      if (got_sigterm) {
        restore_tty();
        if (r_child>0) {
          kill(-r_child, SIGTERM);
          waitpid(r_child, NULL, 0);
        }
        exit(1);
      }

      // Check if r_child exited on its own
      if (r_child>0) {
        int status;
        pid_t w = waitpid(r_child, &status, WNOHANG);
        if (w==r_child) {
          // child exited
          int exit_code;
          int signaled = 0;
          int sig = 0;
          if (WIFEXITED(status)) {
            exit_code = WEXITSTATUS(status);
            signaled = 0;
          } else if (WIFSIGNALED(status)) {
            exit_code = 128 + WTERMSIG(status);
            signaled = 1;
            sig = WTERMSIG(status);
          } else {
            exit_code = 0;
          }
          // Send status to awk
          char *util_name = get_util_name(util_argv, util_argc, flag_s);
          if (signaled) {
            send_status("signal", sig, util_name);
          } else {
            send_status("exit", exit_code, util_name);
          }
          if (flag_z) {
            restore_tty();
            exit(exit_code);
          } else {
            // Wait for next file event to restart
            r_child = -1;
            r_child_exit_code = exit_code;
          }
        }
      }

      // Poll inotify and tty
      struct pollfd pfds[2];
      int nfds = 0;
      pfds[nfds].fd = inotify_fd;
      pfds[nfds].events = POLLIN;
      nfds++;
      if (tty_fd>=0) {
        pfds[nfds].fd = tty_fd;
        pfds[nfds].events = POLLIN;
        nfds++;
      }

      int ret = poll(pfds, nfds, -1);
      if (ret < 0) {
        if (errno==EINTR) continue;
        die("poll");
      }

      // Check tty input
      if (tty_fd>=0) {
        for (int idx=0; idx<nfds; idx++) if (pfds[idx].fd==tty_fd && (pfds[idx].revents & POLLIN)) {
          char c;
          ssize_t n = read(tty_fd, &c, 1);
          if (n==1) {
            if (c=='q' || c=='Q') {
              restore_tty();
              if (r_child>0) {
                kill(-r_child, restart_sig);
                waitpid(r_child, NULL, 0);
              }
              exit(0);
            } else if (c==' ') {
              // trigger restart
              if (r_child>0) {
                kill(-r_child, restart_sig);
                int status;
                waitpid(r_child, &status, 0);
                // After child exits, will restart below via file event logic? Actually space should trigger restart immediately
                // So set trigger and restart
                r_child = -1;
                // Use current trigger_file
                // Build argv
                char **run_argv;
                if (flag_s) {
                  run_argv = util_argv;
                } else {
                  run_argv = malloc((util_argc+1)*sizeof(char*));
                  int replaced=0;
                  for (int j=0;j<util_argc;j++) {
                    if (!replaced && strcmp(util_argv[j], "/_")==0) {
                      run_argv[j]=trigger_file;
                      replaced=1;
                    } else run_argv[j]=util_argv[j];
                  }
                  run_argv[util_argc]=NULL;
                }
                r_child = start_child_r(run_argv, util_argc, trigger_file);
                if (!flag_s) free(run_argv);
              } else {
                // No child running, start one
                char **run_argv;
                if (flag_s) run_argv=util_argv;
                else {
                  run_argv=malloc((util_argc+1)*sizeof(char*));
                  int repl=0;
                  for (int j=0;j<util_argc;j++) {
                    if (!repl && strcmp(util_argv[j], "/_")==0){run_argv[j]=trigger_file; repl=1;} else run_argv[j]=util_argv[j];
                  }
                  run_argv[util_argc]=NULL;
                }
                r_child = start_child_r(run_argv, util_argc, trigger_file);
                if (!flag_s) free(run_argv);
              }
            }
          }
        }
      }

      // Check inotify
      if (pfds[0].fd==inotify_fd && (pfds[0].revents & POLLIN)) {
        char buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
        ssize_t len;
        while ((len = read(inotify_fd, buf, sizeof(buf))) > 0) {
          char *ptr = buf;
          while (ptr < buf+len) {
            struct inotify_event *ev = (struct inotify_event*)ptr;
            // Find watch
            int idx = find_watch_by_wd(ev->wd);
            int didx = -1;
            if (idx==-1) didx = find_dirwatch_by_wd(ev->wd);
            if (idx!=-1) {
              // File watch
              if (ev->mask & (IN_DELETE_SELF | IN_MOVE_SELF | IN_IGNORED)) {
                // file deleted
                fprintf(stderr, "%s: cannot open '%s': No such file or directory\n", progname, watches[idx].orig);
                restore_tty();
                if (r_child>0) {
                  kill(-r_child, SIGTERM);
                  waitpid(r_child, NULL, 0);
                }
                exit(1);
              }
              if (ev->mask & (IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE)) {
                // Trigger restart
                trigger_file = watches[idx].orig;
                // If child running, kill and restart
                if (r_child>0) {
                  kill(-r_child, restart_sig);
                  int status;
                  waitpid(r_child, &status, 0);
                  // status handling already? We'll handle after restart
                  char *util_name = get_util_name(util_argv, util_argc, flag_s);
                  if (WIFEXITED(status)) {
                    send_status("exit", WEXITSTATUS(status), util_name);
                  } else if (WIFSIGNALED(status)) {
                    send_status("signal", WTERMSIG(status), util_name);
                  }
                  r_child = -1;
                }
                // Restart child
                char **run_argv;
                if (flag_s) run_argv=util_argv;
                else {
                  run_argv=malloc((util_argc+1)*sizeof(char*));
                  int repl=0;
                  for (int j=0;j<util_argc;j++) {
                    if (!repl && strcmp(util_argv[j], "/_")==0){run_argv[j]=trigger_file; repl=1;} else run_argv[j]=util_argv[j];
                  }
                  run_argv[util_argc]=NULL;
                }
                r_child = start_child_r(run_argv, util_argc, trigger_file);
                if (!flag_s) free(run_argv);
              }
            } else if (didx!=-1) {
              // Dir watch
              // Check if dir still exists
              struct stat st;
              if (stat(dirwatches[didx].dir_path, &st)!=0) {
                fprintf(stderr, "%s: unable to open directory: '%s'\n", progname, dirwatches[didx].dir_path);
                restore_tty();
                if (r_child>0) { kill(-r_child, SIGTERM); waitpid(r_child,NULL,0); }
                exit(1);
              }
              // List current entries
              int include_dot = (flag_d>=2);
              int n_new;
              char **new_list = list_dir(dirwatches[didx].dir_path, &n_new, include_dot);
              // Compare with old
              int altered = 0;
              if (cmp_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries, new_list, n_new)!=0) {
                altered = 1;
              }
              // Also need to check if file modification in workaround mode?
              // If workaround enabled, treat dir events as file modifications for files whose parent is this dir
              int workaround = getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
              if (workaround && ev->len>0) {
                // ev->name is filename that triggered
                // If that filename matches any file whose parent is this dir, treat as modification
                for (int fi=0; fi<n_files; fi++) {
                  char *parent = my_dirname(files[fi].real);
                  if (parent && strcmp(parent, dirwatches[didx].dir_path)==0) {
                    if (strcmp(ev->name, my_basename(files[fi].real))==0) {
                      // modification
                      trigger_file = files[fi].orig;
                      if (r_child>0) {
                        kill(-r_child, restart_sig);
                        int status; waitpid(r_child,&status,0);
                        char *util_name = get_util_name(util_argv, util_argc, flag_s);
                        if (WIFEXITED(status)) send_status("exit", WEXITSTATUS(status), util_name);
                        else if (WIFSIGNALED(status)) send_status("signal", WTERMSIG(status), util_name);
                        r_child=-1;
                      }
                      char **run_argv;
                      if (flag_s) run_argv=util_argv;
                      else {
                        run_argv=malloc((util_argc+1)*sizeof(char*));
                        int repl=0;
                        for (int j=0;j<util_argc;j++) {
                          if (!repl && strcmp(util_argv[j], "/_")==0){run_argv[j]=trigger_file; repl=1;} else run_argv[j]=util_argv[j];
                        }
                        run_argv[util_argc]=NULL;
                      }
                      r_child = start_child_r(run_argv, util_argc, trigger_file);
                      if (!flag_s) free(run_argv);
                      altered = 0; // don't treat as dir altered, treat as file mod
                      free(parent);
                      break;
                    }
                  }
                  if (parent) free(parent);
                }
              }

              if (altered) {
                // Dir altered: trigger one more run then exit 2 (unless -z)
                // For -r mode, what does dir altered do?
                // Original behavior for -r with -d: when dir altered, it should restart and then exit 2? Let's check earlier tests: with -d and -r, adding file caused restart? We didn't test.
                // For simplicity, for -r mode, if dir altered, we should exit 2 after running once more? Or just exit 2?
                // According to man, -d exit status 2 means files added or removed, and example uses while loop to restart. For -r, does it also exit 2?
                // Likely yes, dir altered should cause exit 2 even in -r mode, after one more run.
                // Let's implement: if altered, trigger one more run if child not running? Actually we already have child running, so we restart child, then after that run, exit 2? But -r persistent child doesn't have "run completes" concept.
                // Simpler: for -r, dir altered causes exit 2 after restarting? Let's check original behavior by testing quickly: we have binary, we can test -r -d.

                // For now, handle like normal: run child again then exit 2.
                free_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries);
                dirwatches[didx].entries = new_list;
                dirwatches[didx].n_entries = n_new;
                // Use orig_for_dir as trigger? Or first file that matches parent?
                trigger_file = dirwatches[didx].orig_for_dir;

                if (r_child>0) {
                  kill(-r_child, restart_sig);
                  int status; waitpid(r_child,&status,0);
                  char *util_name = get_util_name(util_argv, util_argc, flag_s);
                  if (WIFEXITED(status)) send_status("exit", WEXITSTATUS(status), util_name);
                  else if (WIFSIGNALED(status)) send_status("signal", WTERMSIG(status), util_name);
                  r_child=-1;
                }
                // Restart once more
                char **run_argv;
                if (flag_s) run_argv=util_argv;
                else {
                  run_argv=malloc((util_argc+1)*sizeof(char*));
                  int repl=0;
                  for (int j=0;j<util_argc;j++) {
                    if (!repl && strcmp(util_argv[j], "/_")==0){run_argv[j]=trigger_file; repl=1;} else run_argv[j]=util_argv[j];
                  }
                  run_argv[util_argc]=NULL;
                }
                r_child = start_child_r(run_argv, util_argc, trigger_file);
                if (!flag_s) free(run_argv);

                // If not -z, after this run, exit 2? But we have persistent child, not waiting for completion. So we need to decide.
                // Original for -r without -z: when dir altered, does it exit 2 or keep running?
                // Let's approximate: for -r, dir altered should cause exit 2 after restart.
                // We'll sleep a bit then exit 2.
                sleep(1);
                fprintf(stderr, "%s: directory altered\n", progname);
                restore_tty();
                if (r_child>0) { kill(-r_child, SIGTERM); waitpid(r_child,NULL,0); }
                exit(2);
              } else {
                free_str_list(new_list, n_new);
              }
            }
            ptr += sizeof(struct inotify_event) + ev->len;
          }
        }
        if (len==-1 && errno!=EAGAIN) die("read inotify");
      }
    }

  } else {
    // Normal mode
    // For event consolidation
    int pending = 0;
    char *pending_trigger = NULL;
    int pending_dir_altered = 0;
    char *pending_dir_trigger = NULL;

    // Initial run if not -p
    if (!flag_p) {
      // Build argv with trigger
      char **run_argv;
      if (flag_s) {
        run_argv = util_argv;
      } else {
        run_argv = malloc((util_argc+1)*sizeof(char*));
        int replaced=0;
        for (int j=0;j<util_argc;j++) {
          if (!replaced && strcmp(util_argv[j], "/_")==0) {
            run_argv[j]=trigger_file;
            replaced=1;
          } else run_argv[j]=util_argv[j];
        }
        run_argv[util_argc]=NULL;
      }
      int signaled=0, sig=0;
      int code = run_utility_normal(run_argv, util_argc, trigger_file, &signaled, &sig);
      if (!flag_s) free(run_argv);
      char *util_name = get_util_name(util_argv, util_argc, flag_s);
      if (signaled) send_status("signal", sig, util_name);
      else send_status("exit", code, util_name);

      if (flag_z) {
        restore_tty();
        if (awk_fd>=0) close(awk_fd);
        if (awk_pid>0) waitpid(awk_pid,NULL,0);
        exit(code);
      }
    }

    while (1) {
      if (got_sigint) {
        restore_tty();
        if (awk_fd>=0) close(awk_fd);
        if (awk_pid>0) waitpid(awk_pid,NULL,0);
        exit(0);
      }
      if (got_sigterm) {
        restore_tty();
        if (awk_fd>=0) close(awk_fd);
        if (awk_pid>0) waitpid(awk_pid,NULL,0);
        exit(1);
      }

      struct pollfd pfds[2];
      int nfds=0;
      pfds[nfds].fd=inotify_fd;
      pfds[nfds].events=POLLIN;
      nfds++;
      if (tty_fd>=0) {
        pfds[nfds].fd=tty_fd;
        pfds[nfds].events=POLLIN;
        nfds++;
      }

      int ret = poll(pfds, nfds, -1);
      if (ret<0) {
        if (errno==EINTR) continue;
        die("poll");
      }

      // tty input
      if (tty_fd>=0) {
        for (int idx=0; idx<nfds; idx++) if (pfds[idx].fd==tty_fd && (pfds[idx].revents & POLLIN)) {
          char c;
          ssize_t n = read(tty_fd, &c, 1);
          if (n==1) {
            if (c=='q') {
              restore_tty();
              if (awk_fd>=0) close(awk_fd);
              if (awk_pid>0) waitpid(awk_pid,NULL,0);
              exit(0);
            } else if (c==' ') {
              pending = 1;
              pending_trigger = trigger_file;
            }
          }
        }
      }

      // inotify events
      if (pfds[0].fd==inotify_fd && (pfds[0].revents & POLLIN)) {
        char buf[4096];
        ssize_t len;
        while ((len = read(inotify_fd, buf, sizeof(buf))) > 0) {
          char *ptr = buf;
          while (ptr < buf+len) {
            struct inotify_event *ev = (struct inotify_event*)ptr;
            int widx = find_watch_by_wd(ev->wd);
            int didx = find_dirwatch_by_wd(ev->wd);
            if (widx!=-1) {
              if (ev->mask & (IN_DELETE_SELF | IN_MOVE_SELF | IN_IGNORED)) {
                fprintf(stderr, "%s: cannot open '%s': No such file or directory\n", progname, watches[widx].orig);
                restore_tty();
                if (awk_fd>=0) close(awk_fd);
                if (awk_pid>0) waitpid(awk_pid,NULL,0);
                exit(1);
              }
              if (ev->mask & (IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE)) {
                if (flag_a) {
                  // queue each
                  // For -a, we would run multiple times, so we need to handle queue
                  // Simplest: if pending already, we keep as pending and after run we will check again
                  // But for -a we need to run as many times as events
                  // We'll just set pending and also count
                  pending++;
                  pending_trigger = watches[widx].orig;
                } else {
                  pending = 1;
                  pending_trigger = watches[widx].orig;
                }
              }
            } else if (didx!=-1) {
              struct stat st;
              if (stat(dirwatches[didx].dir_path, &st)!=0) {
                fprintf(stderr, "%s: unable to open directory: '%s'\n", progname, dirwatches[didx].dir_path);
                restore_tty();
                if (awk_fd>=0) close(awk_fd);
                if (awk_pid>0) waitpid(awk_pid,NULL,0);
                exit(1);
              }
              int include_dot = (flag_d>=2);
              int n_new;
              char **new_list = list_dir(dirwatches[didx].dir_path, &n_new, include_dot);
              int altered = cmp_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries, new_list, n_new)!=0;
              int workaround = getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
              int handled_as_file_mod = 0;
              if (workaround && ev->len>0) {
                // Check if ev->name matches any file
                for (int fi=0; fi<n_files; fi++) {
                  char *parent = my_dirname(files[fi].real);
                  if (parent && strcmp(parent, dirwatches[didx].dir_path)==0) {
                    if (strcmp(ev->name, my_basename(files[fi].real))==0) {
                      // file mod
                      if (flag_a) pending++;
                      else pending=1;
                      pending_trigger = files[fi].orig;
                      handled_as_file_mod = 1;
                      free(parent);
                      break;
                    }
                  }
                  if (parent) free(parent);
                }
              }
              if (!handled_as_file_mod && altered) {
                // dir altered
                free_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries);
                dirwatches[didx].entries = new_list;
                dirwatches[didx].n_entries = n_new;
                pending_dir_altered = 1;
                pending_dir_trigger = dirwatches[didx].orig_for_dir;
                // Also trigger run
                if (flag_a) pending++;
                else pending=1;
                pending_trigger = dirwatches[didx].orig_for_dir;
              } else if (!handled_as_file_mod) {
                free_str_list(new_list, n_new);
              } else {
                // was file mod, new_list not used for dir altered, free old and keep new? Actually for workaround we still need to update snapshot?
                // For simplicity, update snapshot
                free_str_list(dirwatches[didx].entries, dirwatches[didx].n_entries);
                dirwatches[didx].entries = new_list;
                dirwatches[didx].n_entries = n_new;
              }
            }
            ptr += sizeof(struct inotify_event) + ev->len;
          }
        }
        if (len==-1 && errno!=EAGAIN) die("read inotify");
      }

      // If pending events, run utility
      while (pending) {
        char *use_trigger = pending_trigger ? pending_trigger : trigger_file;
        if (pending_dir_trigger) use_trigger = pending_dir_trigger;
        trigger_file = use_trigger;

        char **run_argv;
        if (flag_s) {
          run_argv = util_argv;
        } else {
          run_argv = malloc((util_argc+1)*sizeof(char*));
          int replaced=0;
          for (int j=0;j<util_argc;j++) {
            if (!replaced && strcmp(util_argv[j], "/_")==0) {
              run_argv[j]=use_trigger;
              replaced=1;
            } else run_argv[j]=util_argv[j];
          }
          run_argv[util_argc]=NULL;
        }

        pending = 0; // will be set again if new events during run? We need to handle events during run

        // If flag_a==0, we want to consolidate events that occur while utility running
        // So we need to poll inotify during child run? Currently run_utility_normal blocks waiting for child, so events during child run would be missed unless we have separate thread or non-blocking check.
        // In original entr, it waits for child to finish before responding to events, but it consolidates events that occurred while utility running (unless -a).
        // So we need to handle: while child running, we should continue to read inotify events but not run again until child finishes, unless -a? Actually -a means respond to all events even while running, but original says -a has no effect with -r. For normal mode, without -a, it consolidates.
        // How to implement consolidation?
        // We can fork and in parent, while waiting for child via waitpid with WNOHANG in loop, poll inotify for events and mark pending.
        // So need to change run_utility_normal to non-blocking wait with poll.

        // For simplicity, we'll implement custom run loop that handles inotify during child execution.

        // Start child
        clear_screen();
        pid_t pid = fork();
        if (pid<0) die("fork");
        if (pid==0) {
          setenv("PAGER", "/bin/cat", 1);
          if (flag_s) {
            char *shell = getenv("SHELL");
            if (!shell) shell = "/bin/sh";
            execlp(shell, shell, "-c", util_argv[0], use_trigger ? use_trigger : "", (char*)NULL);
            fprintf(stderr, "%s: exec %s: %s\n", progname, shell, strerror(errno));
            _exit(127);
          } else {
            execvp(run_argv[0], run_argv);
            fprintf(stderr, "%s: exec %s: %s\n", progname, run_argv[0], strerror(errno));
            _exit(127);
          }
        } else {
          // Parent waits, but also polls inotify and tty
          int child_done = 0;
          int child_status = 0;
          int child_signaled = 0;
          int child_sig = 0;
          int new_pending = 0;
          char *new_pending_trigger = NULL;
          int new_pending_dir_altered = 0;
          char *new_pending_dir_trigger = NULL;

          while (!child_done) {
            struct pollfd pfds2[2];
            int nfds2=0;
            pfds2[nfds2].fd=inotify_fd;
            pfds2[nfds2].events=POLLIN;
            nfds2++;
            if (tty_fd>=0) {
