                  struct inotify_event *ev=(struct inotify_event*)tmp_ptr;
                  int didx=find_dwatch_by_wd(ev->wd);
                  if(didx!=-1 && (ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED))){
                    struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){dir_removal_path=dwatches[didx].dir_path; found_dir_removal=1; break;}
                  }
                  tmp_ptr+=sizeof(struct inotify_event)+ev->len;
                }
                if(found_dir_removal){
                  kill(pid,SIGTERM); waitpid(pid,NULL,0);
                  fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dir_removal_path);
                  restore_tty(); if(!flag_s) free(run_argv); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);
                }
                ptr=buf;
                while(ptr<buf+len){
                  struct inotify_event *ev=(struct inotify_event*)ptr;
                  int fidx=find_fwatch_by_wd(ev->wd);
                  int didx=find_dwatch_by_wd(ev->wd);
                  if(fidx!=-1){
                    if(ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED)){
                      // file deleted during child run, will handle after child finishes
                      if(flag_d){
                        char *parent=my_dirname_dup(fwatches[fidx].watch_path);
                        if(parent){struct stat pst; if(stat(parent,&pst)!=0){kill(pid,SIGTERM); waitpid(pid,NULL,0); fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,parent); free(parent); restore_tty(); if(!flag_s) free(run_argv); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);} free(parent);}
                      }
                      new_pending=1; new_pending_trig=fwatches[fidx].orig;
                    }
                    if(ev->mask&(IN_MODIFY|IN_ATTRIB|IN_CLOSE_WRITE)){
                      if(flag_a) new_pending++; else new_pending=1;
                      new_pending_trig=fwatches[fidx].orig;
                    }
                  }else if(didx!=-1){
                    struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){kill(pid,SIGTERM); waitpid(pid,NULL,0); fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dwatches[didx].dir_path); restore_tty(); if(!flag_s) free(run_argv); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);}
                    int include_dot=(flag_d>=2);
                    int n_new; char **new_list=list_dir(dwatches[didx].dir_path,&n_new,include_dot);
                    int altered=cmp_str_list(dwatches[didx].entries,dwatches[didx].n_entries,new_list,n_new)!=0;
                    int workaround=getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
                    int handled=0;
                    if(workaround && ev->len>0){
                      for(int fi=0;fi<n_files;fi++){
                        char *parent=my_dirname_dup(files[fi].real);
                        if(parent && strcmp(parent,dwatches[didx].dir_path)==0){
                          if(strcmp(ev->name,my_basename_const(files[fi].real))==0){
                            if(flag_a) new_pending++; else new_pending=1;
                            new_pending_trig=files[fi].orig; handled=1; free(parent); break;
                          }
                        }
                        if(parent) free(parent);
                      }
                    }
                    if(!handled && altered){
                      free_str_list(dwatches[didx].entries,dwatches[didx].n_entries);
                      dwatches[didx].entries=new_list;
                      dwatches[didx].n_entries=n_new;
                      new_dir_alt=1; new_dir_trig=dwatches[didx].orig_for_dir;
                      if(flag_a) new_pending++; else new_pending=1;
                      new_pending_trig=dwatches[didx].orig_for_dir;
                    }else if(!handled){
                      free_str_list(new_list,n_new);
                    }else{
                      free_str_list(dwatches[didx].entries,dwatches[didx].n_entries);
                      dwatches[didx].entries=new_list;
                      dwatches[didx].n_entries=n_new;
                    }
                  }
                  ptr+=sizeof(struct inotify_event)+ev->len;
                }
              }
              if(len==-1 && errno!=EAGAIN){perror("read inotify"); exit(1);}
            }
          }
          // child done
          if(!flag_s) free(run_argv);
          int exit_code;
          if(WIFEXITED(child_status)) exit_code=WEXITSTATUS(child_status);
          else if(WIFSIGNALED(child_status)) exit_code=128+WTERMSIG(child_status);
          else exit_code=0;
          char *un=util_name(util_argv,util_argc);
          if(child_signaled) send_status("signal",child_sig,un); else send_status("exit",exit_code,un);
          if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(exit_code);}
          // check file existence
          for(int fi=0;fi<n_files;fi++){struct stat st; if(lstat(files[fi].real,&st)!=0){fprintf(stderr,"%s: cannot open '%s': No such file or directory\n",progname,files[fi].orig); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);}}
          if(new_dir_alt){
            if(new_pending){
              char *use_trig=new_dir_trig?new_dir_trig:new_pending_trig;
              trigger_file=use_trig;
              char **run_argv2;
              if(flag_s) run_argv2=util_argv;
              else{
                run_argv2=malloc((util_argc+1)*sizeof(char*));
                int repl=0;
                for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv2[j]=use_trig; repl=1;} else run_argv2[j]=util_argv[j];}
                run_argv2[util_argc]=NULL;
              }
              int s2=0, sig2=0; int c2=run_normal(run_argv2,util_argc,use_trig,&s2,&sig2);
              if(!flag_s) free(run_argv2);
              char *un2=util_name(util_argv,util_argc);
              if(s2) send_status("signal",sig2,un2); else send_status("exit",c2,un2);
              if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(c2);}
            }
            fprintf(stderr,"%s: directory altered\n",progname);
            restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(2);
          }
          if(flag_a){
            if(new_pending>0){
              // run extra times for -a
              for(int extra=0;extra<new_pending-1;extra++){
                char *use_trig=new_pending_trig;
                trigger_file=use_trig;
                char **run_argv2;
                if(flag_s) run_argv2=util_argv;
                else{
                  run_argv2=malloc((util_argc+1)*sizeof(char*));
                  int repl=0;
                  for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv2[j]=use_trig; repl=1;} else run_argv2[j]=util_argv[j];}
                  run_argv2[util_argc]=NULL;
                }
                int s2=0, sig2=0; int c2=run_normal(run_argv2,util_argc,use_trig,&s2,&sig2);
                if(!flag_s) free(run_argv2);
                char *un2=util_name(util_argv,util_argc);
                if(s2) send_status("signal",sig2,un2); else send_status("exit",c2,un2);
                if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(c2);}
              }
              pending=1; pending_trig=new_pending_trig;
            }else pending=0;
          }else{
            if(new_pending){pending=1; pending_trig=new_pending_trig;}
            else pending=0;
          }
          if(pending_dir_alt){fprintf(stderr,"%s: directory altered\n",progname); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(2);}
        }
      }
    }
  }
  return 0;
}
