actions.command:
# The -r handling is too complex. Let's rewrite the entire file with a cleaner implementation, incorporating lessons learned and simpler logic.

# We'll start fresh, but keep file.

cat > entr.c <<'C'
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/inotify.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <termios.h>
#include <limits.h>
#include <dirent.h>
#include <libgen.h>

static int ev_trace = 0;
static int flag_a = 0;
static int flag_c = 0;
static int flag_d = 0;
static int flag_n = 0;
static int flag_p = 0;
static int flag_r = 0;
static int flag_s = 0;
static int flag_x = 0;
static int flag_z = 0;

static char *progname = "executable";

typedef struct {
  char *orig;
  char *real;
  struct stat st;
  int is_dir;
} FileEnt;

typedef struct {
  char *dir_path;
  char *orig_for_dir;
  char **entries;
  int n_entries;
  int wd;
} DirWatch;

typedef struct {
  char *orig;
  char *watch_path;
  int wd;
} FileWatch;

static FileEnt *files = NULL;
static int n_files = 0;

static FileWatch *fwatches = NULL;
static int n_fwatches = 0;
static int fw_cap = 0;

static DirWatch *dwatches = NULL;
static int n_dwatches = 0;
static int dw_cap = 0;

static int inotify_fd = -1;
static int tty_fd = -1;
static struct termios orig_termios;
static int termios_saved = 0;
static char *trigger_file = NULL;

static int awk_fd = -1;
static pid_t awk_pid = -1;
static char *status_script_path = NULL;

static int restart_sig = SIGTERM;

static volatile sig_atomic_t got_sigint = 0;
static volatile sig_atomic_t got_sigterm = 0;

static void sigint_handler(int sig){got_sigint=1;}
static void sigterm_handler(int sig){got_sigterm=1;}

static void print_usage(int is_help){
  if(is_help){
    fprintf(stderr,"release: 5.7\n");
    fprintf(stderr,"usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    fprintf(stderr,"summary:\n");
    fprintf(stderr,"    -a  Do not consolidate events\n");
    fprintf(stderr,"    -c  Clear screen before execution\n");
    fprintf(stderr,"    -d  Track files added or removed from directories\n");
    fprintf(stderr,"    -n  Non-interactive mode\n");
    fprintf(stderr,"    -p  Wait for first event\n");
    fprintf(stderr,"    -r  Run as a background process, use signal to restart\n");
    fprintf(stderr,"    -s  Evaluate using a shell\n");
    fprintf(stderr,"    -x  Format exit status\n");
    fprintf(stderr,"    -z  Exit after the utility completes\n");
    fprintf(stderr,"docs:\n");
    fprintf(stderr,"    man entr\n");
  }else{
    fprintf(stderr,"release: 5.7\n");
    fprintf(stderr,"usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
    fprintf(stderr,"hint: use -h to display option summary\n");
  }
}

static char *my_basename(char *path){
  char *b=strrchr(path,'/');
  if(b) return b+1;
  return path;
}
static char *my_basename_const(const char *path){
  const char *b=strrchr(path,'/');
  if(b) return (char*)(b+1);
  return (char*)path;
}
static char *my_dirname_dup(const char *path){
  char *copy=strdup(path);
  if(!copy) return NULL;
  char *dir=dirname(copy);
  char *res=strdup(dir);
  free(copy);
  return res;
}
static int is_dotfile(const char *name){return name[0]=='.';}

static char **list_dir(const char *dir_path, int *out_n, int include_dot){
  DIR *d=opendir(dir_path);
  if(!d) return NULL;
  char **list=NULL;
  int n=0, cap=0;
  struct dirent *ent;
  while((ent=readdir(d))!=NULL){
    if(strcmp(ent->d_name,".")==0||strcmp(ent->d_name,"..")==0) continue;
    if(!include_dot && is_dotfile(ent->d_name)) continue;
    if(n>=cap){cap=cap?cap*2:64; list=realloc(list,cap*sizeof(char*));}
    list[n++]=strdup(ent->d_name);
  }
  closedir(d);
  for(int i=0;i<n;i++) for(int j=i+1;j<n;j++) if(strcmp(list[i],list[j])>0){char *tmp=list[i];list[i]=list[j];list[j]=tmp;}
  *out_n=n;
  return list;
}
static int cmp_str_list(char **a,int na,char **b,int nb){
  if(na!=nb) return 1;
  for(int i=0;i<na;i++) if(strcmp(a[i],b[i])!=0) return 1;
  return 0;
}
static void free_str_list(char **list,int n){
  if(!list) return;
  for(int i=0;i<n;i++) free(list[i]);
  free(list);
}
static int find_fwatch_by_wd(int wd){
  for(int i=0;i<n_fwatches;i++) if(fwatches[i].wd==wd) return i;
  return -1;
}
static int find_dwatch_by_wd(int wd){
  for(int i=0;i<n_dwatches;i++) if(dwatches[i].wd==wd) return i;
  return -1;
}
static int find_dwatch_by_path(const char *path){
  for(int i=0;i<n_dwatches;i++) if(strcmp(dwatches[i].dir_path,path)==0) return i;
  return -1;
}
static void add_fwatch(const char *orig,const char *watch_path){
  if(n_fwatches>=fw_cap){fw_cap=fw_cap?fw_cap*2:64; fwatches=realloc(fwatches,fw_cap*sizeof(FileWatch));}
  fwatches[n_fwatches].orig=strdup(orig);
  fwatches[n_fwatches].watch_path=strdup(watch_path);
  fwatches[n_fwatches].wd=-1;
  n_fwatches++;
}
static void add_dwatch(const char *dir_path,const char *orig_for_dir){
  if(find_dwatch_by_path(dir_path)!=-1) return;
  if(n_dwatches>=dw_cap){dw_cap=dw_cap?dw_cap*2:64; dwatches=realloc(dwatches,dw_cap*sizeof(DirWatch));}
  dwatches[n_dwatches].dir_path=strdup(dir_path);
  dwatches[n_dwatches].orig_for_dir=strdup(orig_for_dir);
  dwatches[n_dwatches].entries=NULL;
  dwatches[n_dwatches].n_entries=0;
  dwatches[n_dwatches].wd=-1;
  n_dwatches++;
}
static void setup_inotify(){
  inotify_fd=inotify_init1(IN_NONBLOCK|IN_CLOEXEC);
  if(inotify_fd<0){perror("inotify_init1"); exit(1);}
  if(ev_trace){
    long open_max=sysconf(_SC_OPEN_MAX);
    if(open_max<0) open_max=1024;
    fprintf(stderr,"open_max: %ld\n",open_max);
    if(getenv("ENTR_INOTIFY_WORKAROUND")) fprintf(stderr,"executable: broken inotify workaround enabled\n");
  }
  int follow=getenv("ENTR_FOLLOW_SYMLINK")!=NULL;
  int workaround=getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
  int include_dot=(flag_d>=2);

  // file watches and dir watches collection
  for(int i=0;i<n_files;i++){
    char *real=files[i].real;
    char *orig=files[i].orig;
    if(files[i].is_dir){
      add_dwatch(real,orig);
    }else{
      if(workaround){
        char *parent=my_dirname_dup(real);
        if(parent){add_dwatch(parent,orig); free(parent);}
      }else{
        char *watch_path=real;
        char resolved[PATH_MAX];
        if(follow){
          if(realpath(real,resolved)!=NULL){
            watch_path=resolved;
          }
        }
        add_fwatch(orig,watch_path);
      }
    }
  }
  if(flag_d){
    for(int i=0;i<n_files;i++){
      if(files[i].is_dir) continue;
      char *parent=my_dirname_dup(files[i].real);
      if(!parent) continue;
      add_dwatch(parent,files[i].orig);
      free(parent);
    }
  }

  // create inotify watches
  for(int i=0;i<n_fwatches;i++){
    uint32_t mask=IN_MODIFY|IN_ATTRIB|IN_CLOSE_WRITE|IN_DELETE_SELF|IN_MOVE_SELF;
    if(!follow) mask|=IN_DONT_FOLLOW;
    int wd=inotify_add_watch(inotify_fd,fwatches[i].watch_path,mask);
    fwatches[i].wd=wd;
    if(wd<0 && ev_trace){
      fprintf(stderr,"inotify watch failed for %s: %s\n",fwatches[i].watch_path,strerror(errno));
    }
    if(wd>=0 && ev_trace){
      struct stat st;
      char type_c='r';
      mode_t mode=0644;
      if(lstat(fwatches[i].watch_path,&st)==0){
        mode=st.st_mode&07777;
        if(S_ISDIR(st.st_mode)) type_c='d';
        else if(S_ISREG(st.st_mode)) type_c='r';
        else if(S_ISLNK(st.st_mode)) type_c='l';
      }
      fprintf(stderr,"%d/%d: fflags: 0x%x %c %o %s\n", i, n_fwatches+n_dwatches-1, 2, type_c, mode, fwatches[i].watch_path);
    }
  }
  for(int i=0;i<n_dwatches;i++){
    int n; char **list=list_dir(dwatches[i].dir_path,&n,include_dot);
    dwatches[i].entries=list;
    dwatches[i].n_entries=n;
    uint32_t mask=IN_CREATE|IN_DELETE|IN_MOVED_FROM|IN_MOVED_TO|IN_DELETE_SELF|IN_MOVE_SELF|IN_ATTRIB|IN_MODIFY;
    if(workaround) mask|=IN_CLOSE_WRITE;
    if(!follow) mask|=IN_DONT_FOLLOW;
    int wd=inotify_add_watch(inotify_fd,dwatches[i].dir_path,mask);
    dwatches[i].wd=wd;
    if(wd<0){
      fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dwatches[i].dir_path);
      continue;
    }
    if(ev_trace){
      struct stat st;
      mode_t mode=0700;
      if(stat(dwatches[i].dir_path,&st)==0) mode=st.st_mode&07777;
      int idx=n_fwatches+i;
      int total=n_fwatches+n_dwatches;
      fprintf(stderr,"%d/%d: fflags: 0x%x d %o %s\n", idx, total-1, 2, mode, dwatches[i].dir_path);
    }
  }
}

static int is_valid_type(struct stat *st){
  if(S_ISREG(st->st_mode)) return 1;
  if(S_ISDIR(st->st_mode)) return 1;
  if(S_ISLNK(st->st_mode)) return 1;
  return 0;
}
static void read_file_list(){
  char *line=NULL; size_t len=0; ssize_t nread;
  while((nread=getline(&line,&len,stdin))!=-1){
    while(nread>0 && (line[nread-1]=='\n'||line[nread-1]=='\r')) line[--nread]='\0';
    if(nread==0) continue;
    char *orig=strdup(line);
    struct stat st;
    if(lstat(line,&st)!=0){
      fprintf(stderr,"%s: unable to stat '%s'\n",progname,line);
      free(orig);
      continue;
    }
    if(!is_valid_type(&st)){free(orig); continue;}
    files=realloc(files,(n_files+1)*sizeof(FileEnt));
    files[n_files].orig=orig;
    files[n_files].real=strdup(line);
    files[n_files].st=st;
    files[n_files].is_dir=S_ISDIR(st.st_mode);
    n_files++;
  }
  free(line);
  if(n_files==0){
    fprintf(stderr,"%s: No regular files to watch\n",progname);
    exit(1);
  }
}
static void setup_tty(){
  if(flag_n){tty_fd=-1; return;}
  tty_fd=open("/dev/tty",O_RDWR);
  if(tty_fd<0){
    fprintf(stderr,"%s: unable to get terminal attributes, use '-n' to run non-interactively\n",progname);
    exit(1);
  }
  struct termios t;
  if(tcgetattr(tty_fd,&t)==-1){
    fprintf(stderr,"%s: unable to get terminal attributes, use '-n' to run non-interactively\n",progname);
    exit(1);
  }
  orig_termios=t;
  termios_saved=1;
  t.c_lflag&=~(ICANON|ECHO);
  t.c_cc[VMIN]=1;
  t.c_cc[VTIME]=0;
  tcsetattr(tty_fd,TCSANOW,&t);
}
static void restore_tty(){
  if(termios_saved && tty_fd>=0) tcsetattr(tty_fd,TCSANOW,&orig_termios);
}
static void setup_signals(){
  struct sigaction sa; memset(&sa,0,sizeof(sa));
  sa.sa_handler=sigint_handler; sigaction(SIGINT,&sa,NULL);
  sa.sa_handler=sigterm_handler; sigaction(SIGTERM,&sa,NULL);
  signal(SIGPIPE,SIG_IGN);
}
static int parse_restart_signal(){
  char *env=getenv("ENTR_RESTART_SIGNAL");
  if(!env) return SIGTERM;
  if(strcmp(env,"HUP")==0) return SIGHUP;
  if(strcmp(env,"INT")==0) return SIGINT;
  if(strcmp(env,"QUIT")==0) return SIGQUIT;
  if(strcmp(env,"TERM")==0) return SIGTERM;
  if(strcmp(env,"USR1")==0) return SIGUSR1;
  if(strcmp(env,"USR2")==0) return SIGUSR2;
  return SIGTERM;
}
static void setup_awk(){
  if(!flag_x) return;
  char *env_script=getenv("ENTR_STATUS_SCRIPT");
  char default_path[PATH_MAX];
  if(env_script) status_script_path=strdup(env_script);
  else{
    char *home=getenv("HOME");
    if(!home) home=".";
    snprintf(default_path,sizeof(default_path),"%s/.entr/status.awk",home);
    status_script_path=strdup(default_path);
  }
  struct stat st;
  if(stat(status_script_path,&st)!=0){
    char *copy=strdup(status_script_path);
    char *dir=dirname(copy);
    char tmp[PATH_MAX]; strncpy(tmp,dir,sizeof(tmp)-1); tmp[sizeof(tmp)-1]='\0';
    for(char *p=tmp+1;*p;p++){if(*p=='/'){*p='\0'; mkdir(tmp,0755); *p='/';}}
    mkdir(tmp,0755);
    free(copy);
    FILE *f=fopen(status_script_path,"w");
    if(f){
      fprintf(f,"# http://eradman.com/entrproject/status-filters.html\n");
      fprintf(f,"/^signal/ { print $3, \"terminated by signal\", $2; }\n");
      fprintf(f,"/^exit/ { print $3, \"returned exit code\", $2; }\n");
      fclose(f);
      chmod(status_script_path,0640);
      fprintf(stderr,"entr: created '%s'\n",status_script_path);
    }
  }
  int pipefd[2];
  if(pipe(pipefd)!=0){perror("pipe"); exit(1);}
  awk_pid=fork();
  if(awk_pid<0){perror("fork"); exit(1);}
  if(awk_pid==0){
    close(pipefd[1]);
    dup2(pipefd[0],STDIN_FILENO);
    close(pipefd[0]);
    if(flag_x==1) execlp("awk","awk","-F","|","-f",status_script_path,"-S",(char*)NULL);
