static int run_normal(char **util_argv,int util_argc,const char *trigger,int *signaled,int *sig){
  clear_screen();
  pid_t pid=fork();
  if(pid<0){perror("fork"); exit(1);}
  if(pid==0){
    setenv("PAGER","cat",1);
    if(flag_s){
      char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh";
      execlp(shell,shell,"-c",util_argv[0],trigger?trigger:"",(char*)NULL);
      fprintf(stderr,"%s: exec %s: %s\n",progname,shell,strerror(errno));
      _exit(1);
    }else{
      execvp(util_argv[0],util_argv);
      fprintf(stderr,"%s: exec %s: %s\n",progname,util_argv[0],strerror(errno));
      _exit(1);
    }
  }else{
    int status;
    while(waitpid(pid,&status,0)<0){
      if(errno==EINTR){
        if(got_sigint||got_sigterm) kill(pid,SIGTERM);
        continue;
      }
      break;
    }
    if(WIFEXITED(status)){*signaled=0;*sig=0;return WEXITSTATUS(status);}
    else if(WIFSIGNALED(status)){*signaled=1;*sig=WTERMSIG(status);return 128+WTERMSIG(status);}
