cat > /tmp/test_readd.c <<'C'
#define _GNU_SOURCE
#include <sys/inotify.h>
#include <unistd.h>
#include <stdio.h>
#include <poll.h>
int main(int argc,char *argv[]){
  int fd=inotify_init1(0);
  int wd=inotify_add_watch(fd,argv[1],IN_MODIFY);
  printf("added wd %d\n",wd); fflush(stdout);
  sleep(1);
  inotify_rm_watch(fd,wd);
  printf("removed\n"); fflush(stdout);
  // mod file
  FILE *f=fopen(argv[1],"a");
  fprintf(f,"mod\n");
  fclose(f);
  printf("mod done\n"); fflush(stdout);
  sleep(1);
  wd=inotify_add_watch(fd,argv[1],IN_MODIFY);
  printf("re-added wd %d\n",wd); fflush(stdout);
  struct pollfd pfd;
  pfd.fd=fd; pfd.events=POLLIN;
  int ret=poll(&pfd,1,1000);
  printf("poll ret %d\n",ret);
  if(ret>0){
    char buf[4096];
    ssize_t len=read(fd,buf,sizeof(buf));
    printf("read len %zd\n",len);
    char *ptr=buf;
    while(ptr<buf+len){
      struct inotify_event *ev=(struct inotify_event*)ptr;
      printf("ev mask 0x%x\n",ev->mask);
      ptr+=sizeof(*ev)+ev->len;
    }
  }else{
    printf("no event after re-add\n");
  }
  return 0;
}
C
gcc /tmp/test_readd.c -o /tmp/test_readd
tmpdir=$(mktemp -d)
f="$tmpdir/f"
echo data > "$f"
 /tmp/test_readd "$f" 2>&1
rm -rf "$tmpdir" /tmp/test_readd.c /tmp/test_readd

