 for(int i=0;i<na;i++) if(strcmp(a[i],b[i])!=0) return 1;
 return 0;
}
static void free_list(char **l,int n){if(!l) return; for(int i=0;i<n;i++) free(l[i]); free(l);}
static int find_fwatch(int wd){for(int i=0;i<n_fw;i++) if(fwatches[i].wd==wd) return i; return -1;}
static int find_dwatch(int wd){for(int i=0;i<n_dw;i++) if(dwatches[i].wd==wd) return i; return -1;}
static int find_dwatch_path(const char *p){for(int i=0;i<n_dw;i++) if(strcmp(dwatches[i].dir_path,p)==0) return i; return -1;}
static void add_fwatch(const char *orig,const char *wp){if(n_fw>=fw_cap){fw_cap=fw_cap?fw_cap*2:64; fwatches=realloc(fwatches,fw_cap*sizeof(FileWatch));} fwatches[n_fw].orig=strdup(orig); fwatches[n_fw].watch_path=strdup(wp); fwatches[n_fw].wd=-1; n_fw++;}
static void add_dwatch(const char *dir,const char *orig){if(find_dwatch_path(dir)!=-1) return; if(n_dw>=dw_cap){dw_cap=dw_cap?dw_cap*2:64; dwatches=realloc(dwatches,dw_cap*sizeof(DirWatch));} dwatches[n_dw].dir_path=strdup(dir); dwatches[n_dw].orig_for_dir=strdup(orig); dwatches[n_dw].entries=NULL; dwatches[n_dw].n_entries=0; dwatches[n_dw].wd=-1; n_dw++;}

static void setup_inotify(){
 inotify_fd=inotify_init1(IN_NONBLOCK|IN_CLOEXEC);
 if(inotify_fd<0){perror("inotify_init1"); exit(1);}
 if(ev_trace){
  long om=sysconf(_SC_OPEN_MAX); if(om<0) om=1024;
  fprintf(stderr,"open_max: %ld\n",om);
  if(getenv("ENTR_INOTIFY_WORKAROUND")) fprintf(stderr,"executable: broken inotify workaround enabled\n");
 }
 int follow=getenv("ENTR_FOLLOW_SYMLINK")!=NULL;
 int workaround=getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
 int include_dot=(flag_d>=2);
 for(int i=0;i<n_files;i++){
  char *real=files[i].real; char *orig=files[i].orig;
  if(files[i].is_dir){add_dwatch(real,orig);}
  else{
   if(workaround){char *parent=my_dirname(real); if(parent){add_dwatch(parent,orig); free(parent);}}
   else{
    char *wp=real; char resolved[PATH_MAX];
    if(follow && realpath(real,resolved)!=NULL) wp=resolved;
    add_fwatch(orig,wp);
   }
  }
 }
 if(flag_d){
  for(int i=0;i<n_files;i++){if(files[i].is_dir) continue; char *parent=my_dirname(files[i].real); if(!parent) continue; add_dwatch(parent,files[i].orig); free(parent);}
 }
 for(int i=0;i<n_fw;i++){
  uint32_t mask=IN_MODIFY|IN_ATTRIB|IN_DELETE_SELF|IN_MOVE_SELF;
  if(!follow) mask|=IN_DONT_FOLLOW;
  int wd=inotify_add_watch(inotify_fd,fwatches[i].watch_path,mask);
  fwatches[i].wd=wd;
  if(ev_trace && wd>=0){
   struct stat st; char type_c='r'; mode_t mode=0644;
   if(lstat(fwatches[i].watch_path,&st)==0){mode=st.st_mode&07777; if(S_ISDIR(st.st_mode)) type_c='d'; else if(S_ISREG(st.st_mode)) type_c='r'; else if(S_ISLNK(st.st_mode)) type_c='l';}
   fprintf(stderr,"%d/%d: fflags: 0x%x %c %o %s\n", i, n_fw+n_dw-1, 2, type_c, mode, fwatches[i].watch_path);
  }
 }
 for(int i=0;i<n_dw;i++){
  int n; char **list=list_dir(dwatches[i].dir_path,&n,include_dot);
  dwatches[i].entries=list; dwatches[i].n_entries=n;
  uint32_t mask=IN_CREATE|IN_DELETE|IN_MOVED_FROM|IN_MOVED_TO|IN_DELETE_SELF|IN_MOVE_SELF|IN_ATTRIB|IN_MODIFY;
  if(workaround) mask|=IN_CLOSE_WRITE;
  if(!follow) mask|=IN_DONT_FOLLOW;
  int wd=inotify_add_watch(inotify_fd,dwatches[i].dir_path,mask);
  dwatches[i].wd=wd;
  if(wd<0){fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dwatches[i].dir_path); continue;}
  if(ev_trace){
   struct stat st; mode_t mode=0700; if(stat(dwatches[i].dir_path,&st)==0) mode=st.st_mode&07777;
   fprintf(stderr,"%d/%d: fflags: 0x%x d %o %s\n", n_fw+i, n_fw+n_dw-1, 2, mode, dwatches[i].dir_path);
  }
 }
}
static int valid_type(struct stat *st){return S_ISREG(st->st_mode)||S_ISDIR(st->st_mode)||S_ISLNK(st->st_mode);}
static void read_files(){
 char *line=NULL; size_t len=0; ssize_t nread;
 while((nread=getline(&line,&len,stdin))!=-1){
  while(nread>0 && (line[nread-1]=='\n'||line[nread-1]=='\r')) line[--nread]='\0';
  if(nread==0) continue;
  char *orig=strdup(line);
  struct stat st;
  if(lstat(line,&st)!=0){fprintf(stderr,"%s: unable to stat '%s'\n",progname,line); free(orig); continue;}
  if(!valid_type(&st)){free(orig); continue;}
  files=realloc(files,(n_files+1)*sizeof(FileEnt));
  files[n_files].orig=orig; files[n_files].real=strdup(line); files[n_files].st=st; files[n_files].is_dir=S_ISDIR(st.st_mode); n_files++;
 }
 free(line);
 if(n_files==0){fprintf(stderr,"%s: No regular files to watch\n",progname); exit(1);}
}
static void setup_tty(){
 if(flag_n){tty_fd=-1; return;}
 tty_fd=open("/dev/tty",O_RDWR);
 if(tty_fd<0){fprintf(stderr,"%s: unable to get terminal attributes, use '-n' to run non-interactively\n",progname); exit(1);}
 struct termios t;
 if(tcgetattr(tty_fd,&t)==-1){fprintf(stderr,"%s: unable to get terminal attributes, use '-n' to run non-interactively\n",progname); exit(1);}
 orig_termios=t; termios_saved=1;
 t.c_lflag&=~(ICANON|ECHO); t.c_cc[VMIN]=1; t.c_cc[VTIME]=0;
 tcsetattr(tty_fd,TCSANOW,&t);
}
static void restore_tty(){if(termios_saved&&tty_fd>=0) tcsetattr(tty_fd,TCSANOW,&orig_termios);}
static void setup_signals(){struct sigaction sa; memset(&sa,0,sizeof(sa)); sa.sa_handler=sigint_h; sigaction(SIGINT,&sa,NULL); sa.sa_handler=sigterm_h; sigaction(SIGTERM,&sa,NULL); signal(SIGPIPE,SIG_IGN);}
static int parse_restart_sig(){
 char *env=getenv("ENTR_RESTART_SIGNAL"); if(!env) return SIGTERM;
 if(strcmp(env,"HUP")==0) return SIGHUP;
 if(strcmp(env,"INT")==0) return SIGINT;
 if(strcmp(env,"QUIT")==0) return SIGQUIT;
 if(strcmp(env,"TERM")==0) return SIGTERM;
 if(strcmp(env,"USR1")==0) return SIGUSR1;
 if(strcmp(env,"USR2")==0) return SIGUSR2;
 return SIGTERM;
}
static void setup_awk(){
 if(!flag_x) return;
 char *env_script=getenv("ENTR_STATUS_SCRIPT");
 char default_path[PATH_MAX];
 if(env_script) status_script_path=strdup(env_script);
 else{char *home=getenv("HOME"); if(!home) home="."; snprintf(default_path,sizeof(default_path),"%s/.entr/status.awk",home); status_script_path=strdup(default_path);}
 struct stat st;
 if(stat(status_script_path,&st)!=0){
  char *copy=strdup(status_script_path); char *dir=dirname(copy);
  char tmp[PATH_MAX]; strncpy(tmp,dir,sizeof(tmp)-1); tmp[sizeof(tmp)-1]='\0';
  for(char *p=tmp+1;*p;p++){if(*p=='/'){*p='\0'; mkdir(tmp,0755); *p='/';}}
  mkdir(tmp,0755); free(copy);
  FILE *f=fopen(status_script_path,"w");
  if(f){
   fprintf(f,"# http://eradman.com/entrproject/status-filters.html\n");
   fprintf(f,"/^signal/ { print $3, \"terminated by signal\", $2; }\n");
   fprintf(f,"/^exit/ { print $3, \"returned exit code\", $2; }\n");
   fclose(f); chmod(status_script_path,0640);
   fprintf(stderr,"entr: created '%s'\n",status_script_path);
  }
 }
 int pipefd[2]; if(pipe(pipefd)!=0){perror("pipe"); exit(1);}
 awk_pid=fork();
 if(awk_pid<0){perror("fork"); exit(1);}
 if(awk_pid==0){
  close(pipefd[1]); dup2(pipefd[0],STDIN_FILENO); close(pipefd[0]);
  if(flag_x==1) execlp("awk","awk","-F","|","-f",status_script_path,"-S",(char*)NULL);
  else execlp("awk","awk","-F","|","-f",status_script_path,(char*)NULL);
  perror("awk"); _exit(1);
 }else{close(pipefd[0]); awk_fd=pipefd[1];}
}
static void send_status(const char *type,int code,const char *util){
 if(!flag_x||awk_fd<0) return;
 char buf[1024]; snprintf(buf,sizeof(buf),"%s|%d|%s\n",type,code,util);
 ssize_t n=write(awk_fd,buf,strlen(buf));
 if(n<0 && errno==EPIPE){fprintf(stderr,"%s: status process terminated\n",progname); close(awk_fd); awk_fd=-1; int st; waitpid(awk_pid,&st,0); awk_pid=-1;}
}
static char *util_name_fn(char **argv,int argc){if(flag_s) return "sh"; if(argc>0) return my_basename(argv[0]); return "unknown";}
static void clear_screen_fn(){if(flag_c==1){const char *seq="\033[2J\033[H"; write(STDOUT_FILENO,seq,strlen(seq));} else if(flag_c>=2){const char *seq="\033[2J\033[3J\033[H"; write(STDOUT_FILENO,seq,strlen(seq));}}

static int run_child(char **util_argv,int util_argc,const char *trigger,int *signaled,int *sig){
 clear_screen_fn();
 pid_t pid=fork();
 if(pid<0){perror("fork"); exit(1);}
 if(pid==0){
  setenv("PAGER","cat",1);
  if(flag_s){
   char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh";
   execlp(shell,shell,"-c",util_argv[0],trigger?trigger:"",(char*)NULL);
   fprintf(stderr,"%s: exec %s: %s\n",progname,shell,strerror(errno)); _exit(1);
  }else{
   execvp(util_argv[0],util_argv);
   fprintf(stderr,"%s: exec %s: %s\n",progname,util_argv[0],strerror(errno)); _exit(1);
  }
 }else{
  int status;
  while(waitpid(pid,&status,0)<0){if(errno==EINTR){if(got_sigint||got_sigterm) kill(pid,SIGTERM); continue;} else break;}
  if(WIFEXITED(status)){*signaled=0;*sig=0; return WEXITSTATUS(status);}
  else if(WIFSIGNALED(status)){*signaled=1;*sig=WTERMSIG(status); return 128+WTERMSIG(status);}
  else{*signaled=0;*sig=0; return 0;}
 }
 return 0;
}

static int run_child_with_events(char **util_argv,int util_argc,const char *trigger,int *signaled,int *sig,int *out_pending, char **out_trig, int *out_dir_alt, char **out_dir_trig){
 // For normal mode, run child while polling inotify for events.
 // If flag_a==0, events during run are ignored (except deletion and tty q/space).
 // If flag_a==1, events during run set pending.
 // Returns exit code, and sets out_pending etc for events that occurred during run.

 clear_screen_fn();
 pid_t pid=fork();
 if(pid<0){perror("fork"); exit(1);}
 if(pid==0){
  setenv("PAGER","cat",1);
  if(flag_s){
   char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh";
   execlp(shell,shell,"-c",util_argv[0],trigger?trigger:"",(char*)NULL);
   fprintf(stderr,"%s: exec %s: %s\n",progname,shell,strerror(errno)); _exit(1);
  }else{
   execvp(util_argv[0],util_argv);
   fprintf(stderr,"%s: exec %s: %s\n",progname,util_argv[0],strerror(errno)); _exit(1);
  }
 }else{
  int child_status=0; int child_done=0;
  int pending=0; char *pending_trig=NULL; int dir_alt=0; char *dir_trig=NULL;
  while(!child_done){
   int status; pid_t w=waitpid(pid,&status,WNOHANG);
   if(w==pid){child_done=1; child_status=status; if(WIFEXITED(status)){*signaled=0; *sig=0;} else if(WIFSIGNALED(status)){*signaled=1; *sig=WTERMSIG(status);} break;}
   struct pollfd pfds[2]; int nfds=0;
   pfds[nfds].fd=inotify_fd; pfds[nfds].events=POLLIN; nfds++;
   if(tty_fd>=0){pfds[nfds].fd=tty_fd; pfds[nfds].events=POLLIN; nfds++;}
   int ret=poll(pfds,nfds,100);
   if(ret<0){if(errno==EINTR) continue; perror("poll"); exit(1);}
   if(ret==0) continue;
   if(tty_fd>=0){
    for(int i=0;i<nfds;i++) if(pfds[i].fd==tty_fd && (pfds[i].revents&POLLIN)){
     char c; if(read(tty_fd,&c,1)==1){
      if(c=='q'){kill(pid,SIGTERM); waitpid(pid,NULL,0); restore_tty(); exit(0);}
      else if(c==' '){if(flag_a){pending++; pending_trig=trigger_file?trigger_file:(char*)trigger;} else {pending=1; pending_trig=trigger_file;}}
     }
    }
   }
   if(pfds[0].revents&POLLIN){
    char buf[4096]; ssize_t len;
    while((len=read(inotify_fd,buf,sizeof(buf)))>0){
     char *ptr=buf;
     // check dir removal first
     char *tmp_ptr=buf; char *dir_removal_path=NULL; int found_dir_removal=0;
     while(tmp_ptr<buf+len){
      struct inotify_event *ev=(struct inotify_event*)tmp_ptr;
      int didx=find_dwatch(ev->wd);
      if(didx!=-1 && (ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED))){
       struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){dir_removal_path=dwatches[didx].dir_path; found_dir_removal=1; break;}
      }
      tmp_ptr+=sizeof(struct inotify_event)+ev->len;
     }
     if(found_dir_removal){
      kill(pid,SIGTERM); waitpid(pid,NULL,0);
      fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dir_removal_path);
      restore_tty(); exit(1);
     }
     ptr=buf;
     while(ptr<buf+len){
      struct inotify_event *ev=(struct inotify_event*)ptr;
      int fidx=find_fwatch(ev->wd);
      int didx=find_dwatch(ev->wd);
      if(fidx!=-1){
       if(ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED)){
        // file deleted - always exit 1, even without -a
        if(flag_d){
         char *parent=my_dirname(fwatches[fidx].watch_path);
         if(parent){struct stat pst; if(stat(parent,&pst)!=0){kill(pid,SIGTERM); waitpid(pid,NULL,0); fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,parent); free(parent); restore_tty(); exit(1);} free(parent);}
        }
        kill(pid,SIGTERM); waitpid(pid,NULL,0);
        fprintf(stderr,"%s: cannot open '%s': No such file or directory\n",progname,fwatches[fidx].orig);
        restore_tty(); exit(1);
       }
       if(ev->mask&(IN_MODIFY|IN_ATTRIB)){
        if(flag_a){pending++; pending_trig=fwatches[fidx].orig;}
        // without -a, ignore
       }
      }else if(didx!=-1){
       struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){kill(pid,SIGTERM); waitpid(pid,NULL,0); fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dwatches[didx].dir_path); restore_tty(); exit(1);}
       int include_dot=(flag_d>=2);
       int n_new; char **new_list=list_dir(dwatches[didx].dir_path,&n_new,include_dot);
       int altered=cmp_list(dwatches[didx].entries,dwatches[didx].n_entries,new_list,n_new)!=0;
       int workaround=getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
       int handled=0;
       if(workaround && ev->len>0){
        for(int fi=0;fi<n_files;fi++){
         char *parent=my_dirname(files[fi].real);
         if(parent && strcmp(parent,dwatches[didx].dir_path)==0){
          if(strcmp(ev->name,my_basename_c(files[fi].real))==0){
           if(flag_a){pending++; pending_trig=files[fi].orig;}
           handled=1; free(parent); break;
          }
         }
         if(parent) free(parent);
        }
       }
       if(!handled && altered){
        free_list(dwatches[didx].entries,dwatches[didx].n_entries);
        dwatches[didx].entries=new_list; dwatches[didx].n_entries=n_new;
        dir_alt=1; dir_trig=dwatches[didx].orig_for_dir;
        if(flag_a){pending++; pending_trig=dwatches[didx].orig_for_dir;}
       }else if(!handled){
        free_list(new_list,n_new);
       }else{
        free_list(dwatches[didx].entries,dwatches[didx].n_entries);
        dwatches[didx].entries=new_list; dwatches[didx].n_entries=n_new;
       }
      }
      ptr+=sizeof(struct inotify_event)+ev->len;
     }
    }
    if(len==-1 && errno!=EAGAIN){perror("read inotify"); exit(1);}
   }
  }
  // After child, drain remaining events if not -a (ignore)
  if(!flag_a){
   char dbuf[4096];
   struct pollfd pf; pf.fd=inotify_fd; pf.events=POLLIN;
   while(1){
    int ret=poll(&pf,1,50);
    if(ret<=0) break;
    while(read(inotify_fd,dbuf,sizeof(dbuf))>0){}
   }
  }
  if(WIFEXITED(child_status)) return WEXITSTATUS(child_status);
  else if(WIFSIGNALED(child_status)) return 128+WTERMSIG(child_status);
  else return 0;
  // Also return pending info via out parameters
  // But we need to set out_pending after
  // We'll use pointers set before return - need to restructure

  // This function currently doesn't return pending via out params because we return early
  // We'll handle pending via globals for simplicity in caller
 }
 return 0;
}

