   fprintf(stderr,"entr: created '%s'\n",status_script_path);
  }
 }
 int pipefd[2]; if(pipe(pipefd)!=0){perror("pipe"); exit(1);}
 awk_pid=fork();
 if(awk_pid<0){perror("fork"); exit(1);}
 if(awk_pid==0){
  close(pipefd[1]); dup2(pipefd[0],STDIN_FILENO); close(pipefd[0]);
  if(flag_x==1) execlp("awk","awk","-F","|","-f",status_script_path,"-S",(char*)NULL);
