}
static char *util_name_fn(char **argv,int argc){if(flag_s) return "sh"; if(argc>0) return my_basename(argv[0]); return "unknown";}
static void clear_screen_fn(){if(flag_c==1){const char *seq="\033[2J\033[H"; write(STDOUT_FILENO,seq,strlen(seq));} else if(flag_c>=2){const char *seq="\033[2J\033[3J\033[H"; write(STDOUT_FILENO,seq,strlen(seq));}}

static int run_child(char **util_argv,int util_argc,const char *trigger,int *signaled,int *sig){
 clear_screen_fn();
 pid_t pid=fork();
 if(pid<0){perror("fork"); exit(1);}
 if(pid==0){
  setenv("PAGER","cat",1);
  if(flag_s){
   char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh";
   execlp(shell,shell,"-c",util_argv[0],trigger?trigger:"",(char*)NULL);
   fprintf(stderr,"%s: exec %s: %s\n",progname,shell,strerror(errno)); _exit(1);
  }else{
   execvp(util_argv[0],util_argv);
   fprintf(stderr,"%s: exec %s: %s\n",progname,util_argv[0],strerror(errno)); _exit(1);
  }
 }else{
  int status;
  while(waitpid(pid,&status,0)<0){if(errno==EINTR){if(got_sigint||got_sigterm) kill(pid,SIGTERM); continue;} else break;}
  if(WIFEXITED(status)){*signaled=0;*sig=0; return WEXITSTATUS(status);}
  else if(WIFSIGNALED(status)){*signaled=1;*sig=WTERMSIG(status); return 128+WTERMSIG(status);}
  else{*signaled=0;*sig=0; return 0;}
 }
 return 0;
}

static int run_child_with_events(char **util_argv,int util_argc,const char *trigger,int *signaled,int *sig,int *out_pending, char **out_trig, int *out_dir_alt, char **out_dir_trig){
 // For normal mode, run child while polling inotify for events.
 // If flag_a==0, events during run are ignored (except deletion and tty q/space).
 // If flag_a==1, events during run set pending.
 // Returns exit code, and sets out_pending etc for events that occurred during run.

 clear_screen_fn();
 pid_t pid=fork();
 if(pid<0){perror("fork"); exit(1);}
 if(pid==0){
  setenv("PAGER","cat",1);
  if(flag_s){
   char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh";
   execlp(shell,shell,"-c",util_argv[0],trigger?trigger:"",(char*)NULL);
   fprintf(stderr,"%s: exec %s: %s\n",progname,shell,strerror(errno)); _exit(1);
  }else{
   execvp(util_argv[0],util_argv);
   fprintf(stderr,"%s: exec %s: %s\n",progname,util_argv[0],strerror(errno)); _exit(1);
  }
 }else{
  int child_status=0; int child_done=0;
  int pending=0; char *pending_trig=NULL; int dir_alt=0; char *dir_trig=NULL;
  while(!child_done){
   int status; pid_t w=waitpid(pid,&status,WNOHANG);
   if(w==pid){child_done=1; child_status=status; if(WIFEXITED(status)){*signaled=0; *sig=0;} else if(WIFSIGNALED(status)){*signaled=1; *sig=WTERMSIG(status);} break;}
   struct pollfd pfds[2]; int nfds=0;
   pfds[nfds].fd=inotify_fd; pfds[nfds].events=POLLIN; nfds++;
   if(tty_fd>=0){pfds[nfds].fd=tty_fd; pfds[nfds].events=POLLIN; nfds++;}
   int ret=poll(pfds,nfds,100);
   if(ret<0){if(errno==EINTR) continue; perror("poll"); exit(1);}
   if(ret==0) continue;
   if(tty_fd>=0){
    for(int i=0;i<nfds;i++) if(pfds[i].fd==tty_fd && (pfds[i].revents&POLLIN)){
     char c; if(read(tty_fd,&c,1)==1){
      if(c=='q'){kill(pid,SIGTERM); waitpid(pid,NULL,0); restore_tty(); exit(0);}
      else if(c==' '){if(flag_a){pending++; pending_trig=trigger_file?trigger_file:(char*)trigger;} else {pending=1; pending_trig=trigger_file;}}
     }
    }
   }
   if(pfds[0].revents&POLLIN){
    char buf[4096]; ssize_t len;
    while((len=read(inotify_fd,buf,sizeof(buf)))>0){
     char *ptr=buf;
     // check dir removal first
     char *tmp_ptr=buf; char *dir_removal_path=NULL; int found_dir_removal=0;
     while(tmp_ptr<buf+len){
      struct inotify_event *ev=(struct inotify_event*)tmp_ptr;
      int didx=find_dwatch(ev->wd);
      if(didx!=-1 && (ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED))){
       struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){dir_removal_path=dwatches[didx].dir_path; found_dir_removal=1; break;}
      }
