     if(pid4==0){setpgid(0,0); setenv("PAGER","cat",1); if(flag_s){char *shell=getenv("SHELL"); if(!shell) shell="/bin/sh"; execlp(shell,shell,"-c",util_argv[0],trigger_file?trigger_file:"",(char*)NULL); _exit(1);} else{execvp(run_argv[0],run_argv); _exit(1);} }
     else{setpgid(pid4,pid4); r_child=pid4;}
     if(!flag_s) free(run_argv);
    }
    if(len==-1 && errno!=EAGAIN){perror("read inotify"); exit(1);}
   }
  }
 }else{
  int pending=0; char *pending_trig=NULL; int pending_dir_alt=0; char *pending_dir_trig=NULL;
  if(!flag_p){
   char **run_argv;
   if(flag_s) run_argv=util_argv;
   else{
    run_argv=malloc((util_argc+1)*sizeof(char*));
    int repl=0;
    for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv[j]=trigger_file; repl=1;} else run_argv[j]=util_argv[j];}
    run_argv[util_argc]=NULL;
   }
   int sigd=0,sig=0;
   // Use run_with_pending for initial to handle -a correctly
   int out_p=0; char *out_trig=NULL; int out_dir_alt=0; char *out_dir_trig=NULL;
   int code=run_with_pending(run_argv,util_argc,trigger_file,&sigd,&sig,&out_p,&out_trig,&out_dir_alt,&out_dir_trig);
   if(!flag_s) free(run_argv);
   char *un=util_name_fn(util_argv,util_argc);
   if(sigd) send_status("signal",sig,un); else send_status("exit",code,un);
   if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(code);}
   // If out_pending set and -a, we should have already handled? Actually run_with_pending returns after handling events during run, so out_pending indicates extra runs needed beyond initial
   // For without -a, out_pending will be 0 because we ignore events during run
   // So we need to handle out_pending for -a case: if out_pending, set pending for next runs
   if(flag_a && out_p){
     pending=out_p;
     pending_trig=out_trig;
     pending_dir_alt=out_dir_alt;
     pending_dir_trig=out_dir_trig;
   }
  }
  while(1){
   if(got_sigint){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(0);}
   if(got_sigterm){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);}
   if(!pending){
    struct pollfd pfds[2]; int nfds=0;
    pfds[nfds].fd=inotify_fd; pfds[nfds].events=POLLIN; nfds++;
    if(tty_fd>=0){pfds[nfds].fd=tty_fd; pfds[nfds].events=POLLIN; nfds++;}
    int ret=poll(pfds,nfds,-1);
    if(ret<0){if(errno==EINTR) continue; perror("poll"); exit(1);}
    if(tty_fd>=0){
     for(int idx=0;idx<nfds;idx++) if(pfds[idx].fd==tty_fd && (pfds[idx].revents&POLLIN)){
      char c; if(read(tty_fd,&c,1)==1){
       if(c=='q'){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(0);}
       else if(c==' '){pending=1; pending_trig=trigger_file;}
      }
     }
    }
    if(pfds[0].revents&POLLIN){
     char buf[4096]; ssize_t len;
     while((len=read(inotify_fd,buf,sizeof(buf)))>0){
      char *ptr=buf;
      char *dir_removal_path=NULL; int found_dir_removal=0;
      char *tmp_ptr=buf;
      while(tmp_ptr<buf+len){
       struct inotify_event *ev=(struct inotify_event*)tmp_ptr;
       int didx=find_dwatch(ev->wd);
       if(didx!=-1 && (ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED))){
        struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){dir_removal_path=dwatches[didx].dir_path; found_dir_removal=1; break;}
       }
       tmp_ptr+=sizeof(struct inotify_event)+ev->len;
      }
      if(found_dir_removal){
       fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dir_removal_path);
       restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);
      }
      ptr=buf;
      while(ptr<buf+len){
       struct inotify_event *ev=(struct inotify_event*)ptr;
       int fidx=find_fwatch(ev->wd);
       int didx=find_dwatch(ev->wd);
       if(fidx!=-1){
        if(ev->mask&(IN_DELETE_SELF|IN_MOVE_SELF|IN_IGNORED)){
         if(flag_d){
          char *parent=my_dirname(fwatches[fidx].watch_path);
          if(parent){struct stat pst; if(stat(parent,&pst)!=0){fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,parent); free(parent); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);} free(parent);}
         }
         fprintf(stderr,"%s: cannot open '%s': No such file or directory\n",progname,fwatches[fidx].orig);
         restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);
        }
        if(ev->mask&(IN_MODIFY|IN_ATTRIB)){
         if(flag_a) pending++; else pending=1;
         pending_trig=fwatches[fidx].orig;
        }
       }else if(didx!=-1){
        struct stat st; if(stat(dwatches[didx].dir_path,&st)!=0){fprintf(stderr,"%s: unable to open directory: '%s'\n",progname,dwatches[didx].dir_path); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);}
        int include_dot=(flag_d>=2);
        int n_new; char **new_list=list_dir(dwatches[didx].dir_path,&n_new,include_dot);
        int altered=cmp_list(dwatches[didx].entries,dwatches[didx].n_entries,new_list,n_new)!=0;
        int workaround=getenv("ENTR_INOTIFY_WORKAROUND")!=NULL;
        int handled=0;
        if(workaround && ev->len>0){
         for(int fi=0;fi<n_files;fi++){
          char *parent=my_dirname(files[fi].real);
          if(parent && strcmp(parent,dwatches[didx].dir_path)==0){
           if(strcmp(ev->name,my_basename_c(files[fi].real))==0){
            if(flag_a) pending++; else pending=1;
            pending_trig=files[fi].orig; handled=1; free(parent); break;
           }
          }
          if(parent) free(parent);
         }
        }
        if(!handled && altered){
         free_list(dwatches[didx].entries,dwatches[didx].n_entries);
         dwatches[didx].entries=new_list; dwatches[didx].n_entries=n_new;
         pending_dir_alt=1; pending_dir_trig=dwatches[didx].orig_for_dir;
         if(flag_a) pending++; else pending=1;
         pending_trig=dwatches[didx].orig_for_dir;
        }else if(!handled){
         free_list(new_list,n_new);
        }else{
         free_list(dwatches[didx].entries,dwatches[didx].n_entries);
         dwatches[didx].entries=new_list; dwatches[didx].n_entries=n_new;
        }
       }
       ptr+=sizeof(struct inotify_event)+ev->len;
      }
     }
     if(len==-1 && errno!=EAGAIN){perror("read inotify"); exit(1);}
    }
   }
   while(pending){
    char *use_trig=pending_trig?pending_trig:trigger_file;
    if(pending_dir_trig) use_trig=pending_dir_trig;
    trigger_file=use_trig;
    char **run_argv;
    if(flag_s) run_argv=util_argv;
    else{
     run_argv=malloc((util_argc+1)*sizeof(char*));
     int repl=0;
     for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv[j]=use_trig; repl=1;} else run_argv[j]=util_argv[j];}
     run_argv[util_argc]=NULL;
    }
    int new_pending=0; char *new_pending_trig=NULL; int new_dir_alt=0; char *new_dir_trig=NULL;
    int sigd=0,sig=0;
    int code=run_with_pending(run_argv,util_argc,use_trig,&sigd,&sig,&new_pending,&new_pending_trig,&new_dir_alt,&new_dir_trig);
    if(!flag_s) free(run_argv);
    char *un=util_name_fn(util_argv,util_argc);
    if(sigd) send_status("signal",sig,un); else send_status("exit",code,un);
    if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(code);}
    for(int fi=0;fi<n_files;fi++){struct stat st; if(lstat(files[fi].real,&st)!=0){fprintf(stderr,"%s: cannot open '%s': No such file or directory\n",progname,files[fi].orig); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(1);}}
    if(new_dir_alt){
     if(new_pending){
      char *ut=new_dir_trig?new_dir_trig:new_pending_trig;
      trigger_file=ut;
      char **run_argv2;
      if(flag_s) run_argv2=util_argv;
      else{
       run_argv2=malloc((util_argc+1)*sizeof(char*));
       int repl=0;
       for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv2[j]=ut; repl=1;} else run_argv2[j]=util_argv[j];}
       run_argv2[util_argc]=NULL;
      }
      int s2=0, sig2=0; int c2=run_child(run_argv2,util_argc,ut,&s2,&sig2);
      if(!flag_s) free(run_argv2);
      char *un2=util_name_fn(util_argv,util_argc);
      if(s2) send_status("signal",sig2,un2); else send_status("exit",c2,un2);
      if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(c2);}
     }
     fprintf(stderr,"%s: directory altered\n",progname);
     restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(2);
    }
    if(flag_a){
     if(new_pending>0){
      for(int extra=0;extra<new_pending-1;extra++){
       char *ut=new_pending_trig;
       trigger_file=ut;
       char **run_argv2;
       if(flag_s) run_argv2=util_argv;
       else{
        run_argv2=malloc((util_argc+1)*sizeof(char*));
        int repl=0;
        for(int j=0;j<util_argc;j++){if(!repl && strcmp(util_argv[j],"/_")==0){run_argv2[j]=ut; repl=1;} else run_argv2[j]=util_argv[j];}
        run_argv2[util_argc]=NULL;
       }
       int s2=0, sig2=0; int c2=run_child(run_argv2,util_argc,ut,&s2,&sig2);
       if(!flag_s) free(run_argv2);
       char *un2=util_name_fn(util_argv,util_argc);
       if(s2) send_status("signal",sig2,un2); else send_status("exit",c2,un2);
       if(flag_z){restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(c2);}
      }
      pending=1; pending_trig=new_pending_trig;
     }else pending=0;
    }else{
     pending=0;
    }
    if(pending_dir_alt){fprintf(stderr,"%s: directory altered\n",progname); restore_tty(); if(awk_fd>=0) close(awk_fd); if(awk_pid>0) waitpid(awk_pid,NULL,0); exit(2);}
   }
  }
 }
 return 0;
}
